50:   border-radius:4px;background:rgba(255,255,255,.06);font-family:var(--body);font-size:9px;
51:   font-weight:700;letter-spacing:.04em;color:#fff;vertical-align:1px;
52: }
53: #app{position:fixed;inset:0;overflow:hidden;isolation:isolate;background:#040711}
54: #stage{position:absolute;inset:0;width:100%;height:100%;display:block}
55: .atmosphere{position:absolute;inset:0;pointer-events:none;z-index:2}
56: .vignette{
57:   position:absolute;inset:0;background:
58:     radial-gradient(ellipse at 50% 44%, transparent 38%, rgba(0,3,10,.25) 76%, rgba(0,2,7,.68) 100%),
59:     linear-gradient(to bottom, rgba(1,4,12,.25), transparent 20%, transparent 74%, rgba(1,4,10,.54));
60: }
61: .grain{
62:   position:absolute;inset:-60%;opacity:.055;pointer-events:none;
63:   background-image:url("data:image/svg+xml,%3Csvg viewBox='0 0 220 220' xmlns='http://www.w3.org/2000/svg'%3E%3Cfilter id='n'%3E%3CfeTurbulence type='fractalNoise' baseFrequency='.9' numOctaves='4' stitchTiles='stitch'/%3E%3C/filter%3E%3Crect width='100%25' height='100%25' filter='url(%23n)' opacity='.7'/%3E%3C/svg%3E");
64:   animation:grainShift .45s steps(2) infinite;mix-blend-mode:overlay;
65: }
66: @keyframes grainShift{0%{transform:translate(0,0)}25%{transform:translate(2%,-1%)}50%{transform:translate(-1%,2%)}75%{transform:translate(1%,1%)}100%{transform:translate(-2%,-1%)}}
