68: /* ---------- screens ---------- */
69: .screen{
70:   position:absolute;inset:0;z-index:4;opacity:0;visibility:hidden;
71:   transition:opacity .42s ease,visibility .42s;
72:   pointer-events:none;
73: }
74: .screen.is-active{opacity:1;visibility:visible}
75: .screen.is-active button,.screen.is-active a,.screen.is-active .interactive{pointer-events:auto}
76: .screen.is-leaving{opacity:0;transition:opacity .3s ease}
77: .glass{
78:   background:linear-gradient(145deg,rgba(15,25,45,.82),rgba(5,11,22,.78));
79:   border:1px solid var(--line);
80:   box-shadow:0 30px 80px rgba(0,0,0,.38),inset 0 1px 0 rgba(255,255,255,.07);
81:   backdrop-filter:blur(20px) saturate(1.25);
82:   -webkit-backdrop-filter:blur(20px) saturate(1.25);
83: }
84: 
85: /* ---------- typography helpers ---------- */
86: .section-kicker{
87:   font-size:10px;font-weight:800;letter-spacing:.26em;color:var(--gold);
88:   text-transform:uppercase;display:flex;align-items:center;gap:9px;
89: }
90: .section-kicker::before{content:'';width:18px;height:1px;background:currentColor;opacity:.75}
91: .panel-title{font-family:var(--display);font-weight:700;font-size:clamp(42px,5vw,64px);line-height:.95;letter-spacing:-.025em;text-transform:uppercase}
92: .panel-title em{font-style:italic;color:var(--gold);font-weight:600}
93: .panel-sub{color:var(--muted);font-size:13px;line-height:1.6;margin-top:12px}
