95: /* ---------- topbar ---------- */
96: .topbar{
97:   position:absolute;top:0;left:0;right:0;z-index:10;height:82px;
98:   padding:calc(20px + var(--safe-top)) clamp(22px,3.6vw,58px) 0;
99:   display:flex;align-items:flex-start;justify-content:space-between;gap:24px;
100: }
101: .brand{display:flex;align-items:center;gap:13px;text-decoration:none;color:inherit}
102: .rings{display:block;width:50px;filter:drop-shadow(0 2px 12px rgba(255,206,96,.22))}
103: .rings svg{display:block;width:100%;overflow:visible}
104: .brand-copy{display:flex;flex-direction:column;line-height:1}
105: .brand-copy b{font-family:var(--display);font-size:24px;font-weight:800;letter-spacing:.12em}
106: .brand-copy small{font-size:7px;letter-spacing:.38em;color:var(--muted);margin-top:4px;font-weight:700}
107: .topbar-center{
108:   position:absolute;left:50%;top:31px;transform:translateX(-50%);
109:   font-size:8px;letter-spacing:.25em;font-weight:700;color:rgba(255,255,255,.55);
110:   display:flex;align-items:center;gap:9px;white-space:nowrap;
111: }
112: .live-dot{width:6px;height:6px;border-radius:50%;background:var(--red);box-shadow:0 0 10px var(--red);animation:pulse 1.8s infinite}
113: @keyframes pulse{0%,100%{opacity:1;transform:scale(1)}50%{opacity:.35;transform:scale(.75)}}
114: .slash{opacity:.3}
115: .topbar-actions{display:flex;gap:8px;align-items:center}
116: .icon-btn{
117:   width:40px;height:40px;border-radius:50%;border:1px solid rgba(255,255,255,.14);
118:   background:rgba(8,14,26,.4);backdrop-filter:blur(12px);display:grid;place-items:center;
119:   transition:.2s ease;color:rgba(255,255,255,.8);
