121: .icon-btn:hover{background:rgba(247,201,80,.12);border-color:rgba(247,201,80,.5);color:var(--gold);transform:translateY(-1px)}
122: .icon-btn svg{width:18px;height:18px}
123: #soundBtn .ico-muted{display:none}
124: #soundBtn.is-muted .ico-sound{display:none}
125: #soundBtn.is-muted .ico-muted{display:block}
