127: /* ---------- main menu ---------- */
128: #menu{
129:   background:
130:     linear-gradient(90deg,rgba(3,7,16,.92) 0%,rgba(3,7,16,.68) 31%,rgba(3,7,16,.12) 58%,rgba(3,7,16,.55) 100%),
131:     linear-gradient(to bottom,rgba(2,5,12,.38),transparent 24%,transparent 72%,rgba(2,5,12,.82));
132: }
133: .menu-content{
134:   position:absolute;inset:0;padding:100px clamp(24px,5.5vw,92px) 80px;
135:   display:grid;grid-template-columns:minmax(0,1fr) clamp(310px,29vw,430px);
