140: @keyframes riseIn{to{transform:translateY(0);opacity:1}}
141: .eyebrow{
142:   display:flex;align-items:center;gap:11px;font-size:9px;font-weight:800;
143:   letter-spacing:.29em;color:rgba(245,241,229,.68);text-transform:uppercase;margin-bottom:20px;
144: }
145: .eyebrow span{
146:   color:var(--ink);background:var(--gold);padding:4px 7px 3px;border-radius:2px;
147:   font-weight:800;letter-spacing:.14em;font-size:9px;
148: }
149: .eyebrow i{width:28px;height:1px;background:rgba(255,255,255,.28);margin-left:3px}
150: .season-toggle{
151:   display:inline-flex;align-items:center;gap:11px;margin:0 0 14px;padding:8px 12px 8px 10px;
152:   border:1px solid rgba(247,201,80,.32);border-radius:40px;background:rgba(8,15,28,.62);
153:   color:rgba(255,255,255,.9);backdrop-filter:blur(14px);text-align:left;
154:   box-shadow:inset 0 1px 0 rgba(255,255,255,.08),0 8px 24px rgba(0,0,0,.2);
