158: .season-icon{font-size:15px;line-height:1;color:var(--gold);width:22px;text-align:center}
159: .season-copy{display:flex;flex-direction:column;gap:1px;line-height:1.15}
160: .season-copy b{font-family:var(--display);font-size:11px;letter-spacing:.16em;font-weight:700}
161: .season-copy small{font-size:7px;letter-spacing:.11em;font-weight:700;color:rgba(247,201,80,.72)}
162: .season-track{position:relative;width:30px;height:15px;border-radius:30px;background:rgba(255,255,255,.12);border:1px solid rgba(255,255,255,.16);flex:0 0 auto}
163: .season-track i{position:absolute;top:2px;left:2px;width:9px;height:9px;border-radius:50%;background:var(--gold);box-shadow:0 0 8px rgba(247,201,80,.7);transition:transform .25s cubic-bezier(.2,.8,.2,1),background .25s}
164: body.season-winter .season-track i{transform:translateX(15px);background:#8fe4ff;box-shadow:0 0 8px rgba(143,228,255,.85)}
165: body.season-winter .season-icon{color:#8fe4ff}
166: body.season-winter{--gold:#8fe4ff;--gold-2:#49b9e6;--gold-3:#2b7196}
167: body.season-winter .ring-1{stroke:#8fe4ff}
168: body.season-winter .programme-status{color:#8fe4ff}
169: .mega-title{position:relative;line-height:.72;margin-left:-4px}
170: .mega-title .word{
171:   display:block;font-family:var(--display);font-size:clamp(112px,13.6vw,214px);font-weight:900;
172:   letter-spacing:-.035em;line-height:.72;
173:   background:linear-gradient(175deg,#fffdf6 8%,#eadfc8 37%,#f7c950 68%,#b67619 100%);
