182: .subword{display:flex;align-items:center;gap:14px;margin-top:12px;margin-left:7px}
183: .subword b{font-family:var(--display);font-size:clamp(30px,3.2vw,48px);font-weight:500;letter-spacing:.19em;color:rgba(255,255,255,.85)}
184: .subword i{font-family:var(--display);font-size:clamp(23px,2.3vw,34px);font-style:italic;color:var(--gold);font-weight:400}
185: .tagline{
186:   font-size:clamp(12px,1.05vw,14px);line-height:1.8;color:rgba(235,240,250,.6);
187:   margin:25px 0 30px;letter-spacing:.015em;
