191:   position:relative;overflow:hidden;display:inline-flex;align-items:center;justify-content:center;gap:16px;
192:   border-radius:3px;text-transform:uppercase;text-decoration:none;transition:transform .2s ease,box-shadow .2s ease,background .2s ease;
193:   letter-spacing:.08em;isolation:isolate;
194: }
195: .btn:hover{transform:translateY(-2px)}
196: .btn:active{transform:translateY(0) scale(.99)}
197: .btn-gold{
198:   color:#171203;
199:   background:linear-gradient(120deg,#ffe19a 0%,#f7c950 38%,#e6a52d 78%,#f7ce64 100%);
200:   box-shadow:0 14px 34px rgba(218,155,36,.2),inset 0 1px 0 rgba(255,255,255,.72),inset 0 -2px 0 rgba(92,48,0,.2);
201:   border:1px solid rgba(255,230,165,.7);
