225: .campaign-facts>div{display:flex;flex-direction:column;gap:2px}
226: .campaign-facts b{font-family:var(--display);font-size:22px;font-weight:600;letter-spacing:.03em;line-height:1;color:rgba(255,255,255,.9)}
227: .campaign-facts span{font-size:7px;font-weight:800;letter-spacing:.22em;color:rgba(255,255,255,.34)}
228: .campaign-facts .pb-fact b{color:var(--gold)}
229: .campaign-facts .pb-fact{margin-left:auto;text-align:right}
