231: /* programme card */
232: .programme-card{
233:   align-self:center;border-radius:4px;padding:0;overflow:hidden;
234:   transform:translateX(18px);opacity:0;
235: }
236: #menu.is-active .programme-card{animation:slideIn .8s .28s cubic-bezier(.2,.8,.2,1) forwards}
237: @keyframes slideIn{to{transform:translateX(0);opacity:1}}
238: .programme-head{
239:   display:flex;justify-content:space-between;align-items:center;padding:18px 20px 16px;
240:   border-bottom:1px solid var(--line-soft);font-size:8px;font-weight:800;letter-spacing:.22em;color:rgba(255,255,255,.52);
241: }
242: .programme-status{color:var(--green);display:flex;align-items:center;gap:6px}
243: .programme-status::before{content:'';width:5px;height:5px;border-radius:50%;background:var(--green);box-shadow:0 0 8px var(--green)}
244: .programme-row{
245:   width:100%;display:grid;grid-template-columns:30px 38px 1fr auto 14px;align-items:center;gap:10px;
246:   padding:17px 18px;border-bottom:1px solid var(--line-soft);text-align:left;transition:.25s ease;
247:   position:relative;overflow:hidden;
248: }
