254: .prog-icon svg{width:21px;height:21px}
255: .prog-copy{display:flex;flex-direction:column;gap:3px;min-width:0}
256: .prog-copy b{font-family:var(--display);font-size:17px;letter-spacing:.055em;font-weight:600;white-space:nowrap}
257: .prog-copy small{font-size:8px;letter-spacing:.03em;color:rgba(255,255,255,.34);white-space:nowrap;overflow:hidden;text-overflow:ellipsis}
258: .prog-best{font-size:8px;font-weight:700;letter-spacing:.09em;color:rgba(255,255,255,.32);white-space:nowrap}
259: .prog-arrow{font-size:12px;color:rgba(255,255,255,.25);transition:.2s}
