261: .programme-foot{display:flex;justify-content:space-between;padding:13px 19px;font-size:7px;letter-spacing:.18em;font-weight:800;color:rgba(255,255,255,.28);background:rgba(0,0,0,.16)}
262: 
263: /* footer */
264: .menu-footer{
265:   position:absolute;left:0;right:0;bottom:0;height:46px;padding:0 clamp(22px,3.6vw,58px) var(--safe-bottom);
