275: .footer-meta{display:flex;gap:22px;font-size:7px;letter-spacing:.2em;font-weight:700;color:rgba(255,255,255,.26);flex:0 0 auto}
276: 
277: /* ---------- generic modal ---------- */
278: .modal-screen{z-index:30;background:rgba(2,5,12,.28)}
279: .backdrop{position:absolute;inset:0;background:rgba(2,5,12,.7);backdrop-filter:blur(14px);-webkit-backdrop-filter:blur(14px);pointer-events:auto}
280: .modal-panel{
281:   position:absolute;left:50%;top:50%;transform:translate(-50%,-50%) translateY(18px);
282:   width:min(1000px,calc(100vw - 40px));border-radius:5px;padding:42px;
