122: class Particles {
123:   constructor() { this.list = []; }
124:   spawn(o) {
125:     if (this.list.length > 900) this.list.shift();
126:     const life = o.life ?? 0.7;
127:     this.list.push({
128:       x: o.x, y: o.y, vx: o.vx ?? 0, vy: o.vy ?? 0,
129:       life, maxLife: life, size: o.size ?? 2, color: o.color ?? '#fff',
130:       gravity: o.gravity ?? 0, drag: o.drag ?? 0, shape: o.shape ?? 'circle',
131:       rot: o.rot ?? 0, vr: o.vr ?? 0, alpha: o.alpha ?? 1
132:     });
133:   }
134:   burst(x, y, count, color, speed = 120, life = 0.7, gravity = 160) {
135:     for (let i = 0; i < count; i++) {
136:       const a = rand(0, TAU);
137:       const v = speed * rand(0.25, 1);
138:       this.spawn({
139:         x, y, vx: Math.cos(a) * v, vy: Math.sin(a) * v - rand(0, 45),
140:         life: life * rand(0.55, 1.2), size: rand(1, 3.5), color,
141:         gravity, drag: 0.8, alpha: rand(0.35, 0.9)
142:       });
143:     }
144:   }
145:   confetti(n = 60, W, H) {
146:     const colors = ['#f7c950', '#f7f1dc', '#80e5ff', '#d9a42c', '#ff7766', '#75e3a4'];
147:     for (let i = 0; i < n; i++) {
148:       this.spawn({
149:         x: rand(0, W), y: rand(-H * 0.2, H * 0.1),
150:         vx: rand(-45, 45), vy: rand(50, 190), life: rand(2.5, 5),
151:         size: rand(2, 5.5), color: colors[Math.floor(rand(0, colors.length))],
152:         gravity: 28, drag: 0.1, shape: 'confetti', rot: rand(0, TAU), vr: rand(-8, 8), alpha: rand(0.6, 1)
153:       });
154:     }
155:   }
156:   clear() { this.list.length = 0; }
157:   update(dt) {
158:     for (let i = this.list.length - 1; i >= 0; i--) {
159:       const p = this.list[i];
160:       p.life -= dt;
161:       if (p.life <= 0) { this.list.splice(i, 1); continue; }
162:       p.vy += p.gravity * dt;
163:       if (p.drag) {
164:         const d = Math.exp(-p.drag * dt);
165:         p.vx *= d; p.vy *= d;
166:       }
167:       p.x += p.vx * dt;
168:       p.y += p.vy * dt;
169:       p.rot += p.vr * dt;
170:     }
171:   }
172:   draw(ctx) {
173:     for (const p of this.list) {
174:       const a = clamp(p.life / p.maxLife, 0, 1) * p.alpha;
175:       ctx.save();
176:       ctx.globalAlpha = a;
177:       ctx.fillStyle = p.color;
178:       ctx.translate(p.x, p.y);
179:       if (p.shape === 'confetti') {
180:         ctx.rotate(p.rot);
181:         ctx.fillRect(-p.size / 2, -p.size * 1.4, p.size, p.size * 2.8);
182:       } else if (p.shape === 'streak') {
183:         ctx.rotate(p.rot);
184:         ctx.fillRect(-p.size * 2.5, -p.size * 0.4, p.size * 5, p.size * 0.8);
185:       } else {
186:         ctx.beginPath();
187:         ctx.arc(0, 0, Math.max(0.3, p.size * (0.4 + a * 0.6)), 0, TAU);
188:         ctx.fill();
189:       }
190:       ctx.restore();
191:     }
192:   }
193: }
