817:     drawAthlete(ctx, {
818:       x: hx, y: gy, scale,
819:       phase: this.menuT * 0.78,
820:       pose: 'victory',
821:       speed: 0,
822:       kit: KITS.player,
823:       flip: true,
824:       glow: 0.4,
825:       shadow: 1.15
826:     });
827:     // A slim golden light rim on the floor.
828:     ctx.save();
829:     ctx.globalCompositeOperation = 'screen';
830:     const floor = ctx.createRadialGradient(hx, gy + 4, 0, hx, gy + 4, 110 * scale);
831:     floor.addColorStop(0, 'rgba(247,201,80,.12)');
832:     floor.addColorStop(1, 'rgba(247,201,80,0)');
833:     ctx.fillStyle = floor;
834:     ctx.beginPath(); ctx.ellipse(hx, gy + 4, 110 * scale, 13 * scale, 0, 0, TAU); ctx.fill();
