857:   /* ---------------------------------------------------------------- */
858:   loop(now) {
859:     const dt = Math.min(0.1, Math.max(0.001, (now - this.last) / 1000));
860:     this.last = now;
861:     if (!this.paused) this.update(dt);
862:     this.render();
863:     requestAnimationFrame(this.loop);
864:   }
865: 
866:   update(dt) {
867:     this.menuT += dt;
868:     this.world.update(dt * (this.paused ? 0.22 : 1));
869:     this.particles.update(dt);
870:     this.shake *= Math.exp(-7.5 * dt);
871:     if (this.miniTimer > 0) this.miniTimer -= dt;
872: 
873:     switch (this.state) {
874:       case 'menu':
875:       case 'guide':
876:         break;
877:       case 'intro':
878:         if (this.currentEvent) this.currentEvent.phase += dt * 0.55;
879:         break;
880:       case 'countdown':
881:         this.updateCountdown(dt);
882:         break;
883:       case 'false-start':
884:         this.updateFalseStart(dt);
885:         break;
886:       case 'running':
887:         if (this.currentEvent) this.currentEvent.update(dt);
888:         if (this.goHideTimer > 0) {
889:           this.goHideTimer -= dt;
890:           if (this.goHideTimer <= 0) this.hideCountdown();
891:         }
892:         if (this.miniTimer <= 0) this.renderMiniBoard();
893:         this.applyHud();
894:         break;
895:       case 'results':
896:         if (this.miniTimer <= 0) this.renderMiniBoard();
897:         break;
898:       case 'ceremony':
899:         this.ceremonyT += dt;
900:         this.lastFirework -= dt;
901:         if (this.lastFirework <= 0) {
902:           this.lastFirework = rand(0.8, 1.7);
903:           this.world.addFirework(rand(this.W * 0.15, this.W * 0.85), rand(this.H * 0.12, this.H * 0.4));
904:           this.sound.setCrowd(0.035);
905:         }
906:         break;
907:       default:
908:         break;
909:     }
910:     if (this.state !== 'running' && this.miniTimer <= 0) this.renderMiniBoard();
911:   }
