1014:   applyHud() {
1015:     if (!this.hudData) return;
1016:     const d = this.hudData;
1017:     if (d.clock !== undefined) {
1018:       const unit = d.clockUnit ? `<span>${d.clockUnit}</span>` : '';
1019:       const next = `${d.clock}${unit}`;
1020:       const el = document.getElementById('hudClock');
1021:       if (el.innerHTML !== next) el.innerHTML = next;
1022:     }
1023:     if (d.clockLabel) document.getElementById('clockLabel').textContent = d.clockLabel;
1024:     if (d.place !== undefined) {
1025:       const n = Number(String(d.place).replace(/\D/g, ''));
1026:       const next = n ? ordinal(n) : '—';
1027:       const el = document.getElementById('hudPlace');
1028:       if (el.textContent !== next) el.textContent = next;
1029:     }
1030:     if (d.meter !== undefined) {
1031:       const pct = clamp((d.meter / (d.meterMax || 12)) * 100, 0, 100);
1032:       document.getElementById('meterFill').style.width = `${pct.toFixed(1)}%`;
1033:       document.getElementById('meterValue').textContent = (Math.round(d.meter * 10) / 10).toFixed(1);
1034:     }
1035:     if (d.meterUnit) document.querySelector('.meter-head small').textContent = d.meterUnit;
1036:     if (d.meterLabel) document.getElementById('meterLabel').textContent = d.meterLabel;
1037:     if (d.cadence !== undefined) {
1038:       const dots = document.querySelectorAll('#cadenceOrbit i');
1039:       dots.forEach((dot, i) => dot.classList.toggle('on', i < Math.round(d.cadence * 3)));
1040:     }
1041:     if (d.prompt) {
1042:       const prompt = document.getElementById('hudPrompt');
1043:       prompt.classList.toggle('is-on', !!d.prompt.visible);
1044:       prompt.classList.toggle('pulse', !!d.prompt.pulse);
1045:       if (d.prompt.visible) {
1046:         if (d.prompt.key) {
1047:           document.getElementById('promptKey').textContent = d.prompt.key;
1048:           document.getElementById('promptKey').classList.toggle('is-tap', String(d.prompt.key).length > 2);
1049:         }
1050:         if (d.prompt.title) document.getElementById('promptTitle').textContent = d.prompt.title;
1051:         if (d.prompt.sub) document.getElementById('promptSub').textContent = d.prompt.sub;
1052:       }
1053:     }
1054:     if (d.action !== undefined) {
1055:       const action = document.getElementById('actionBtn');
1056:       if (action) {
1057:         action.classList.toggle('is-hot', !!d.actionHot);
