281:     ctx.beginPath(); ctx.arc(mx - mr * 0.32, my + mr * 0.34, mr * 0.16, 0, TAU); ctx.fill();
282:     ctx.globalAlpha = 1;
283: 
284:     // Thin clouds, low-lit by the stadium.
285:     ctx.save();
286:     for (let i = 0; i < 4; i++) {
287:       const y = H * (0.12 + i * 0.072);
288:       const x = W * (0.15 + i * 0.22) + Math.sin(this.t * 0.02 + i) * 30;
289:       const g = ctx.createRadialGradient(x, y, 0, x, y, W * 0.3);
290:       g.addColorStop(0, `rgba(118,132,164,${0.035 + i * 0.008})`);
291:       g.addColorStop(1, 'rgba(118,132,164,0)');
292:       ctx.fillStyle = g;
293:       ctx.beginPath();
294:       ctx.ellipse(x, y, W * 0.3, H * 0.055, -0.05, 0, TAU);
295:       ctx.fill();
296:     }
297:     ctx.restore();
