300:   drawCity(ctx) {
301:     const W = this.W, H = this.H;
302:     const base = H * 0.505;
303:     const r = seeded(88);
304:     if (this.season === 'winter') {
305:       this.drawMountains(ctx, base);
306:       return;
307:     }
308:     ctx.save();
309:     ctx.globalAlpha = 0.72;
310:     for (let i = 0; i < 34; i++) {
311:       const bw = 9 + r() * 32;
312:       const bh = 15 + r() * H * 0.09;
313:       const x = r() * W;
314:       const y = base - bh;
315:       ctx.fillStyle = i % 4 === 0 ? '#0a1526' : '#07101f';
316:       ctx.fillRect(x, y, bw, bh);
317:       if (r() > 0.35) {
318:         ctx.fillStyle = 'rgba(255,191,104,.36)';
319:         for (let wy = y + 5; wy < base - 4; wy += 7) {
320:           if (r() > 0.58) ctx.fillRect(x + 3 + r() * Math.max(1, bw - 7), wy, 1.3, 1.3);
321:         }
322:       }
323:     }
324:     ctx.restore();
325:     const haze = ctx.createLinearGradient(0, base - 90, 0, base + 15);
326:     haze.addColorStop(0, 'rgba(4,10,20,0)');
327:     haze.addColorStop(1, 'rgba(5,11,21,.86)');
328:     ctx.fillStyle = haze;
329:     ctx.fillRect(0, base - 100, W, 115);
330:   }
