332:   drawMountains(ctx, base) {
333:     const W = this.W, H = this.H;
334:     // Aurora curtains.
335:     ctx.save();
336:     ctx.globalCompositeOperation = 'screen';
337:     for (let i = 0; i < 3; i++) {
338:       const top = H * (0.055 + i * 0.042);
339:       const amp = H * (0.03 + i * 0.012);
340:       const g = ctx.createLinearGradient(0, top, 0, top + H * 0.2);
341:       g.addColorStop(0, 'rgba(90,255,205,0)');
342:       g.addColorStop(0.35, `rgba(84,236,204,${0.085 - i * 0.018})`);
343:       g.addColorStop(0.66, `rgba(88,170,255,${0.055 - i * 0.012})`);
344:       g.addColorStop(1, 'rgba(80,140,255,0)');
345:       ctx.fillStyle = g;
346:       ctx.beginPath();
347:       ctx.moveTo(-20, top);
348:       for (let x = -20; x <= W + 20; x += 24) {
349:         const y = top + Math.sin(x * 0.006 + this.t * 0.22 + i * 1.7) * amp + Math.sin(x * 0.021 - this.t * 0.14 + i) * amp * 0.35;
350:         ctx.lineTo(x, y);
351:       }
352:       ctx.lineTo(W + 20, top + H * 0.22);
353:       for (let x = W + 20; x >= -20; x -= 24) {
354:         const y = top + H * 0.2 + Math.sin(x * 0.005 - this.t * 0.2 + i * 2.2) * amp * 0.8;
355:         ctx.lineTo(x, y);
356:       }
357:       ctx.closePath();
358:       ctx.fill();
359:     }
360:     ctx.restore();
361: 
362:     // Layered snow mountains.
363:     const layers = [
364:       { base: base + 6, amp: H * 0.13, color: '#0b2234', cap: 'rgba(214,240,255,.5)', seed: 31, n: 9 },
365:       { base: base + 12, amp: H * 0.085, color: '#0a1a2a', cap: 'rgba(228,246,255,.66)', seed: 77, n: 12 },
366:       { base: base + 18, amp: H * 0.05, color: '#071322', cap: 'rgba(240,250,255,.8)', seed: 19, n: 16 }
367:     ];
368:     for (const layer of layers) {
369:       const r = seeded(layer.seed);
370:       const peaks = [];
371:       for (let i = 0; i < layer.n; i++) {
372:         const x = -W * 0.08 + (i / (layer.n - 1)) * W * 1.16 + (r() - 0.5) * W * 0.03;
373:         const y = layer.base - layer.amp * (0.5 + r() * 0.7);
374:         peaks.push({ x, y });
375:       }
376:       ctx.fillStyle = layer.color;
377:       ctx.beginPath();
378:       ctx.moveTo(-30, layer.base);
379:       ctx.lineTo(-30, peaks[0].y + layer.amp * 0.3);
380:       for (let i = 0; i < peaks.length; i++) {
381:         const p = peaks[i];
382:         ctx.lineTo(p.x, p.y);
383:         const next = peaks[i + 1];
384:         if (next) {
385:           const vx = (p.x + next.x) / 2 + (r() - 0.5) * W * 0.02;
386:           ctx.lineTo(vx, layer.base - layer.amp * 0.12);
387:         }
388:       }
389:       ctx.lineTo(W + 30, peaks[peaks.length - 1].y + layer.amp * 0.3);
390:       ctx.lineTo(W + 30, layer.base + 6);
391:       ctx.closePath();
392:       ctx.fill();
393:       // summit caps
394:       ctx.fillStyle = layer.cap;
395:       for (const p of peaks) {
396:         const h = layer.amp * 0.26;
397:         ctx.beginPath();
398:         ctx.moveTo(p.x, p.y);
399:         ctx.lineTo(p.x - h * 0.8, p.y + h);
400:         ctx.lineTo(p.x - h * 0.28, p.y + h * 0.7);
401:         ctx.lineTo(p.x + h * 0.12, p.y + h * 1.02);
402:         ctx.lineTo(p.x + h * 0.82, p.y + h);
403:         ctx.closePath();
404:         ctx.fill();
405:       }
406:     }
407:     const haze = ctx.createLinearGradient(0, base - 70, 0, base + 16);
408:     haze.addColorStop(0, 'rgba(6,18,30,0)');
409:     haze.addColorStop(1, 'rgba(7,18,30,.9)');
410:     ctx.fillStyle = haze;
411:     ctx.fillRect(0, base - 80, W, 100);
412:   }
