414:   drawRoof(ctx) {
415:     const W = this.W, H = this.H;
416:     const topY = H * 0.105;
417:     const botY = H * 0.212;
418: 
419:     // A suspended canopy band: sky stays visible above the stadium.
420:     const canopy = ctx.createLinearGradient(0, topY, 0, botY);
421:     canopy.addColorStop(0, '#0b1625');
422:     canopy.addColorStop(0.58, '#07111f');
423:     canopy.addColorStop(1, '#030810');
424:     ctx.fillStyle = canopy;
425:     ctx.beginPath();
426:     ctx.moveTo(-20, topY);
427:     ctx.lineTo(W + 20, topY - H * 0.014);
428:     ctx.lineTo(W + 20, botY - H * 0.016);
429:     ctx.quadraticCurveTo(W * 0.78, botY + H * 0.003, W * 0.56, botY - H * 0.006);
430:     ctx.quadraticCurveTo(W * 0.32, botY - H * 0.015, W * 0.12, botY + H * 0.004);
431:     ctx.quadraticCurveTo(W * 0.03, botY + H * 0.01, -20, botY - H * 0.002);
432:     ctx.closePath();
433:     ctx.fill();
434: 
435:     // leading edge highlight
436:     ctx.strokeStyle = 'rgba(137,169,205,.2)';
437:     ctx.lineWidth = 1.15;
438:     ctx.beginPath();
439:     ctx.moveTo(0, botY - H * 0.002);
440:     ctx.quadraticCurveTo(W * 0.12, botY + H * 0.008, W * 0.3, botY - H * 0.008);
441:     ctx.quadraticCurveTo(W * 0.56, botY - H * 0.012, W * 0.78, botY + H * 0.003);
442:     ctx.quadraticCurveTo(W * 0.92, botY + H * 0.008, W, botY - H * 0.014);
443:     ctx.stroke();
444: 
445:     // roof trusses and diagonal lattice
446:     ctx.strokeStyle = 'rgba(111,141,181,.12)';
447:     ctx.lineWidth = 0.75;
448:     for (let i = 0; i < 13; i++) {
449:       const x = (i / 12) * W;
450:       const yTop = topY - (x / W) * H * 0.014;
451:       ctx.beginPath();
452:       ctx.moveTo(x, yTop);
453:       ctx.lineTo(x, botY - H * 0.012);
454:       ctx.stroke();
455:     }
456:     ctx.strokeStyle = 'rgba(123,153,191,.055)';
457:     for (let i = 0; i < 7; i++) {
458:       const y = topY + i * H * 0.019;
459:       ctx.beginPath();
460:       ctx.moveTo(0, y);
461:       ctx.lineTo(W, y - H * 0.014);
462:       ctx.stroke();
463:     }
464:     // warm service lights under the canopy
465:     ctx.save();
466:     ctx.globalCompositeOperation = 'screen';
467:     for (let i = 0; i < 10; i++) {
468:       const x = W * (0.06 + i * 0.1);
469:       const y = botY - H * 0.017;
470:       const g = ctx.createRadialGradient(x, y, 0, x, y, 7);
471:       g.addColorStop(0, 'rgba(255,235,184,.35)');
472:       g.addColorStop(1, 'rgba(255,220,150,0)');
473:       ctx.fillStyle = g;
474:       ctx.beginPath(); ctx.arc(x, y, 7, 0, TAU); ctx.fill();
475:     }
476:     ctx.restore();
477:   }
