479:   drawFloodlights(ctx) {
480:     const W = this.W, H = this.H;
481:     const towers = [
482:       { x: W * 0.075, h: H * 0.085, scale: 1.05 },
483:       { x: W * 0.925, h: H * 0.075, scale: 1.0 },
484:       { x: W * 0.52, h: H * 0.07, scale: 0.74, faint: true }
485:     ];
486:     for (const tw of towers) {
487:       const topY = tw.h;
488:       const bankY = H * 0.16;
489:       const bankW = 58 * tw.scale * this.u / 0.9;
490:       const bankH = 25 * tw.scale * this.u / 0.9;
491:       // mast
492:       ctx.strokeStyle = 'rgba(126,150,183,.24)';
493:       ctx.lineWidth = 1.3 * tw.scale;
494:       ctx.beginPath(); ctx.moveTo(tw.x - 7, bankY); ctx.lineTo(tw.x - 2, topY); ctx.stroke();
495:       ctx.beginPath(); ctx.moveTo(tw.x + 7, bankY); ctx.lineTo(tw.x + 2, topY); ctx.stroke();
496:       for (let i = 0; i < 6; i++) {
497:         const yy = lerp(bankY, topY, i / 6);
498:         const spread = lerp(7, 2, i / 6);
499:         ctx.beginPath(); ctx.moveTo(tw.x - spread, yy); ctx.lineTo(tw.x + spread, yy); ctx.stroke();
500:       }
501:       // light bank
502:       const bx = tw.x - bankW / 2, by = bankY - bankH;
503:       ctx.save();
504:       ctx.globalAlpha = tw.faint ? 0.56 : 0.9;
505:       ctx.fillStyle = '#111b2a';
506:       ctx.strokeStyle = 'rgba(190,208,232,.27)';
507:       ctx.lineWidth = 1;
508:       ctx.beginPath();
509:       ctx.roundRect ? ctx.roundRect(bx, by, bankW, bankH, 2) : ctx.rect(bx, by, bankW, bankH);
510:       ctx.fill(); ctx.stroke();
511:       for (let row = 0; row < 2; row++) {
512:         for (let col = 0; col < 5; col++) {
513:           const lx = bx + 7 + col * (bankW - 14) / 4;
514:           const ly = by + 7 + row * 10;
515:           const lg = ctx.createRadialGradient(lx, ly, 0, lx, ly, 5.5);
516:           lg.addColorStop(0, 'rgba(255,252,226,1)');
517:           lg.addColorStop(0.3, 'rgba(255,225,166,.72)');
518:           lg.addColorStop(1, 'rgba(255,205,120,0)');
519:           ctx.fillStyle = lg;
520:           ctx.beginPath(); ctx.arc(lx, ly, 5.5, 0, TAU); ctx.fill();
521:           ctx.fillStyle = '#fff9de';
522:           ctx.beginPath(); ctx.arc(lx, ly, 1.35, 0, TAU); ctx.fill();
523:         }
524:       }
525:       ctx.restore();
526: 
527:       // beams of light
528:       ctx.save();
529:       ctx.globalCompositeOperation = 'screen';
530:       const beamAlpha = tw.faint ? 0.032 : 0.062;
531:       const beam = ctx.createLinearGradient(tw.x, bankY, tw.x + (W * 0.5 - tw.x) * 0.34, H * 0.63);
532:       beam.addColorStop(0, `rgba(255,247,215,${beamAlpha})`);
533:       beam.addColorStop(0.5, `rgba(255,225,165,${beamAlpha * 0.35})`);
534:       beam.addColorStop(1, 'rgba(255,220,160,0)');
535:       ctx.fillStyle = beam;
536:       ctx.beginPath();
537:       ctx.moveTo(bx, by + bankH);
538:       ctx.lineTo(bx + bankW, by + bankH);
539:       ctx.lineTo(tw.x + bankW * 2.4, H * 0.69);
540:       ctx.lineTo(tw.x - bankW * 2.4, H * 0.69);
541:       ctx.closePath();
542:       ctx.fill();
543:       ctx.restore();
544:     }
545:   }
