547:   drawCrowd(ctx) {
548:     const W = this.W, H = this.H;
549:     if (!this.crowd) return;
550:     const top = H * 0.245;
551:     const bottom = H * 0.53;
552:     const height = bottom - top;
553: 
554:     // Concrete fascia between the canopy and the stands, with a live LED strip.
555:     const fasciaTop = H * 0.214;
556:     const fasciaH = top - fasciaTop;
557:     const fascia = ctx.createLinearGradient(0, fasciaTop, 0, top);
558:     fascia.addColorStop(0, '#0a1526');
559:     fascia.addColorStop(0.55, '#060d19');
560:     fascia.addColorStop(1, '#030810');
561:     ctx.fillStyle = fascia;
562:     ctx.fillRect(0, fasciaTop, W, fasciaH);
563:     ctx.strokeStyle = 'rgba(141,171,207,.16)';
564:     ctx.lineWidth = 1;
565:     ctx.beginPath(); ctx.moveTo(0, fasciaTop + 0.5); ctx.lineTo(W, fasciaTop + 0.5); ctx.stroke();
566:     // scrolling stadium name on the fascia
567:     const fasciaFont = `600 ${Math.max(7, fasciaH * 0.38)}px "Barlow Condensed", sans-serif`;
568:     ctx.save();
569:     ctx.beginPath(); ctx.rect(0, fasciaTop, W, fasciaH); ctx.clip();
570:     ctx.font = fasciaFont;
571:     ctx.textBaseline = 'middle';
572:     ctx.fillStyle = 'rgba(247,201,80,.55)';
573:     ctx.shadowColor = 'rgba(247,201,80,.5)';
574:     ctx.shadowBlur = 6;
575:     const fasciaMsg = this.season === 'winter'
576:       ? 'OLYMPIA STADIUM   •   WINTER OLYMPIC GAMES   •   SAPPORO 2026   •   '
577:       : 'OLYMPIA STADIUM   •   WORLD OLYMPIC GAMES   •   PARIS 2026   •   ';
578:     const fw = ctx.measureText(fasciaMsg).width;
579:     const foff = -((this.t * 16) % fw);
580:     for (let x = foff; x < W + fw; x += fw) ctx.fillText(fasciaMsg, x, fasciaTop + fasciaH * 0.55);
581:     ctx.restore();
582:     ctx.fillStyle = 'rgba(247,201,80,.28)';
583:     ctx.fillRect(0, top - 1.5, W, 1.2);
584: 
585:     const cw = this.crowdW * (W / this.W);
586:     const offset = -((this.camX * 2.1) % cw + cw) % cw;
587:     const grad = ctx.createLinearGradient(0, top, 0, bottom);
588:     grad.addColorStop(0, 'rgba(8,16,30,.34)');
589:     grad.addColorStop(0.34, 'rgba(9,17,31,.06)');
590:     grad.addColorStop(1, 'rgba(3,8,17,.46)');
591:     ctx.save();
592:     ctx.beginPath();
593:     ctx.moveTo(0, top + H * 0.012);
594:     ctx.quadraticCurveTo(W * 0.22, top - H * 0.01, W * 0.46, top + H * 0.004);
595:     ctx.quadraticCurveTo(W * 0.72, top + H * 0.016, W, top - H * 0.006);
596:     ctx.lineTo(W, bottom + H * 0.012);
597:     ctx.lineTo(0, bottom + H * 0.022);
598:     ctx.closePath();
599:     ctx.clip();
600:     ctx.globalAlpha = 0.96;
601:     for (let i = -1; i < 3; i++) {
602:       ctx.drawImage(this.crowd, offset + i * cw, top, cw, height);
603:     }
604:     ctx.globalAlpha = 1;
605:     // warm wash from the floodlights over the near stand
606:     ctx.save();
607:     ctx.globalCompositeOperation = 'screen';
608:     const warm = ctx.createRadialGradient(W * 0.52, top + height * 0.12, 0, W * 0.52, top + height * 0.12, W * 0.62);
609:     warm.addColorStop(0, this.season === 'winter' ? 'rgba(160,224,255,.14)' : 'rgba(255,183,108,.15)');
610:     warm.addColorStop(0.55, this.season === 'winter' ? 'rgba(110,190,240,.05)' : 'rgba(255,154,92,.05)');
611:     warm.addColorStop(1, this.season === 'winter' ? 'rgba(90,170,230,0)' : 'rgba(255,140,90,0)');
612:     ctx.fillStyle = warm;
613:     ctx.fillRect(0, top, W, height);
614:     ctx.restore();
615:     ctx.fillStyle = grad;
616:     ctx.fillRect(0, top, W, height);
617:     ctx.restore();
618: 
619:     // tier ledges and stair aisles
620:     ctx.save();
621:     for (let row = 0; row < 7; row++) {
622:       const y = top + (row / 7) * height;
623:       ctx.strokeStyle = `rgba(131,151,177,${0.075 + row * 0.006})`;
624:       ctx.lineWidth = 0.8;
625:       ctx.beginPath();
626:       ctx.moveTo(0, y + 7);
627:       ctx.quadraticCurveTo(W * 0.5, y + 1, W, y + 7);
628:       ctx.stroke();
629:     }
630:     for (let i = 1; i < 12; i++) {
631:       const x = (i / 12) * W;
632:       ctx.strokeStyle = 'rgba(2,6,14,.3)';
633:       ctx.lineWidth = 3.5;
634:       ctx.beginPath();
635:       ctx.moveTo(x, top + 4);
636:       ctx.lineTo(x, bottom);
637:       ctx.stroke();
638:     }
639:     // dark rail at the bottom of the stands
640:     ctx.fillStyle = 'rgba(3,8,17,.72)';
641:     ctx.fillRect(0, bottom - H * 0.008, W, H * 0.02);
642:     ctx.strokeStyle = 'rgba(178,198,220,.12)';
643:     ctx.lineWidth = 1;
644:     ctx.beginPath(); ctx.moveTo(0, bottom - H * 0.006); ctx.lineTo(W, bottom - H * 0.002); ctx.stroke();
645:     ctx.restore();
646: 
647:     // phone flashes
648:     ctx.save();
649:     ctx.globalCompositeOperation = 'screen';
650:     for (const f of this.flashes) {
651:       if (f.life > 0) {
652:         const a = f.life / 0.26;
653:         const g = ctx.createRadialGradient(f.x, f.y, 0, f.x, f.y, 11);
654:         g.addColorStop(0, `rgba(255,250,226,${0.9 * a})`);
655:         g.addColorStop(0.25, `rgba(255,240,195,${0.45 * a})`);
656:         g.addColorStop(1, 'rgba(255,230,180,0)');
657:         ctx.fillStyle = g;
658:         ctx.beginPath(); ctx.arc(f.x, f.y, 11, 0, TAU); ctx.fill();
659:       }
660:     }
661:     ctx.restore();
662: 
663:     // A handful of supporter flags along the front rail.
664:     const flags = ['#e9c94f', '#79e2ff', '#ff6d60', '#7ef0a9', '#f3ede0'];
665:     ctx.save();
666:     for (let i = 0; i < 7; i++) {
667:       const fx = W * (0.055 + i * 0.145);
668:       const fy = bottom - H * 0.004;
669:       const fh = H * (0.022 + (i % 3) * 0.003);
670:       const wave = Math.sin(this.t * 2.1 + i * 1.7) * fh * 0.14;
671:       ctx.strokeStyle = 'rgba(175,196,220,.4)';
672:       ctx.lineWidth = 1;
673:       ctx.beginPath(); ctx.moveTo(fx, fy); ctx.lineTo(fx, fy - fh * 1.6); ctx.stroke();
674:       ctx.fillStyle = flags[i % flags.length];
675:       ctx.globalAlpha = 0.55;
676:       ctx.beginPath();
677:       ctx.moveTo(fx, fy - fh * 1.6);
678:       ctx.quadraticCurveTo(fx + fh * 0.7, fy - fh * 1.5 + wave, fx + fh * 1.22, fy - fh * 1.3 + wave);
679:       ctx.lineTo(fx, fy - fh * 0.95);
680:       ctx.closePath();
681:       ctx.fill();
682:       ctx.globalAlpha = 1;
683:     }
684:     ctx.restore();
685:   }
