687:   drawLedRibbon(ctx, opts = {}) {
688:     const W = this.W, H = this.H;
689:     const y = H * 0.528;
690:     const h = H * 0.022;
691:     ctx.fillStyle = '#030810';
692:     ctx.fillRect(0, y, W, h);
693:     ctx.strokeStyle = 'rgba(255,255,255,.09)';
694:     ctx.lineWidth = 1;
695:     ctx.beginPath(); ctx.moveTo(0, y); ctx.lineTo(W, y); ctx.stroke();
696:     ctx.beginPath(); ctx.moveTo(0, y + h); ctx.lineTo(W, y + h); ctx.stroke();
697: 
698:     const msg = opts.ribbon || (this.season === 'winter'
699:       ? 'OLYMPIA 2026  •  WINTER SESSION  •  SNOW & ICE  •  CHASE THE GOLD  •  '
700:       : 'OLYMPIA 2026  •  NIGHT SESSION  •  100M FINAL  •  CHASE THE GOLD  •  ');
701:     const font = `600 ${Math.round(h * 0.48)}px "Barlow Condensed", sans-serif`;
702:     ctx.font = font;
703:     const textW = ctx.measureText(msg).width;
704:     const offset = -((this.t * 28) % textW);
705:     ctx.save();
706:     ctx.beginPath(); ctx.rect(0, y, W, h); ctx.clip();
707:     ctx.textBaseline = 'middle';
708:     ctx.fillStyle = 'rgba(247,201,80,.9)';
709:     ctx.shadowColor = 'rgba(247,201,80,.6)';
710:     ctx.shadowBlur = 8;
711:     for (let x = offset; x < W + textW; x += textW) {
712:       ctx.fillText(msg, x, y + h * 0.54);
713:     }
714:     ctx.shadowBlur = 0;
715:     // panel seams
716:     ctx.fillStyle = 'rgba(0,0,0,.45)';
717:     for (let x = 80; x < W; x += 150) ctx.fillRect(x, y, 1, h);
718:     ctx.restore();
719:   }
