721:   drawJumbotron(ctx, opts = {}) {
722:     const W = this.W, H = this.H;
723:     const mode = opts.mode || this.mode;
724:     if (mode === 'menu') {
725:       const bw = Math.min(W * 0.18, 255);
726:       const bh = bw * 0.57;
727:       const x = W * 0.73 - bw / 2;
728:       const y = H * 0.12;
729:       this.drawBoardBox(ctx, x, y, bw, bh, 'OLYMPIA', '26', this.season === 'winter' ? 'WINTER SESSION' : 'NIGHT SESSION', this.season === 'winter' ? 'SAPPORO' : '20:26');
730:       return;
731:     }
732:     if (mode === 'ceremony') {
733:       const bw = Math.min(W * 0.2, 280);
734:       const bh = bw * 0.55;
735:       this.drawBoardBox(ctx, W * 0.71 - bw / 2, H * 0.115, bw, bh, 'OLYMPIA', '26', 'THE PODIUM', 'GOLD');
736:       return;
737:     }
738:     const bw = Math.min(W * 0.2, 270);
739:     const bh = bw * 0.52;
740:     this.drawBoardBox(
741:       ctx, W * 0.74 - bw / 2, H * 0.13, bw, bh,
742:       opts.top ?? opts.boardTop ?? 'OLYMPIA',
743:       opts.big ?? opts.boardBig ?? '100M',
744:       opts.sub ?? opts.boardSub ?? 'FINAL',
745:       opts.value ?? opts.boardValue ?? '0.00'
746:     );
747:   }
