749:   drawBoardBox(ctx, x, y, w, h, top, big, sub, value) {
750:     ctx.save();
751:     // support cables
752:     ctx.strokeStyle = 'rgba(120,143,172,.24)';
753:     ctx.lineWidth = 1;
754:     ctx.beginPath(); ctx.moveTo(x + w * 0.18, y); ctx.lineTo(x + w * 0.13, 0); ctx.stroke();
755:     ctx.beginPath(); ctx.moveTo(x + w * 0.82, y); ctx.lineTo(x + w * 0.87, 0); ctx.stroke();
756:     // frame
757:     ctx.fillStyle = '#050a12';
758:     ctx.strokeStyle = 'rgba(150,175,205,.3)';
759:     ctx.lineWidth = 1.3;
760:     ctx.beginPath();
761:     if (ctx.roundRect) ctx.roundRect(x, y, w, h, 3); else ctx.rect(x, y, w, h);
762:     ctx.fill(); ctx.stroke();
763:     // screen
764:     const pad = Math.max(4, w * 0.025);
765:     const sx = x + pad, sy = y + pad, sw = w - pad * 2, sh = h - pad * 2;
766:     const bg = ctx.createLinearGradient(sx, sy, sx, sy + sh);
767:     bg.addColorStop(0, '#102f3d');
768:     bg.addColorStop(0.5, '#071b2b');
769:     bg.addColorStop(1, '#030c16');
770:     ctx.fillStyle = bg;
771:     ctx.fillRect(sx, sy, sw, sh);
772:     ctx.globalAlpha = 0.18;
773:     ctx.fillStyle = '#65e3ff';
774:     for (let yy = sy; yy < sy + sh; yy += 3) ctx.fillRect(sx, yy, sw, 0.5);
775:     ctx.globalAlpha = 1;
776:     // scan glow
777:     const glow = ctx.createLinearGradient(sx, sy, sx, sy + sh);
778:     glow.addColorStop(0, 'rgba(83,205,255,.1)');
779:     glow.addColorStop(1, 'rgba(15,82,130,.02)');
780:     ctx.fillStyle = glow;
781:     ctx.fillRect(sx, sy, sw, sh);
782: 
783:     ctx.textAlign = 'center';
784:     ctx.textBaseline = 'middle';
785:     ctx.fillStyle = 'rgba(247,201,80,.9)';
786:     ctx.font = `700 ${Math.max(7, w * 0.042)}px "Barlow Condensed", sans-serif`;
787:     ctx.fillText(top, x + w / 2, sy + sh * 0.14);
788:     ctx.fillStyle = '#f3ead3';
789:     ctx.font = `800 ${Math.max(22, w * 0.24)}px "Barlow Condensed", sans-serif`;
790:     ctx.fillText(big, x + w / 2, sy + sh * 0.43);
791:     ctx.fillStyle = 'rgba(144,229,255,.9)';
792:     ctx.font = `600 ${Math.max(7, w * 0.052)}px "Barlow Condensed", sans-serif`;
793:     ctx.fillText(sub, x + w / 2, sy + sh * 0.68);
794:     ctx.fillStyle = '#f7c950';
795:     ctx.font = `600 ${Math.max(9, w * 0.075)}px "Barlow Condensed", sans-serif`;
796:     ctx.fillText(value, x + w / 2, sy + sh * 0.87);
797:     // screen glare
798:     ctx.globalAlpha = 0.08;
799:     ctx.fillStyle = '#ffffff';
800:     ctx.beginPath();
801:     ctx.moveTo(sx, sy); ctx.lineTo(sx + sw * 0.72, sy); ctx.lineTo(sx, sy + sh * 0.6); ctx.closePath(); ctx.fill();
802:     ctx.restore();
803:   }
