805:   /* ------------------------------------------------------------------ */
806:   /*  GROUND                                                             */
807:   /* ------------------------------------------------------------------ */
808:   drawGround(ctx, opts = {}) {
809:     const W = this.W, H = this.H;
810:     const mode = opts.mode || this.mode;
811:     const L = this.getLayout(mode);
812:     const winter = this.season === 'winter';
813: 
814:     // infield / grass behind the track
815:     const grassTop = H * 0.545;
816:     const grassBottom = L.top + 2;
817:     const grass = ctx.createLinearGradient(0, grassTop, 0, grassBottom);
818:     if (winter) {
819:       grass.addColorStop(0, '#0a1a2c');
820:       grass.addColorStop(0.55, '#163448');
821:       grass.addColorStop(1, '#24536a');
822:     } else {
823:       grass.addColorStop(0, '#061a17');
824:       grass.addColorStop(0.55, '#0a2c24');
825:       grass.addColorStop(1, '#0d3528');
826:     }
827:     ctx.fillStyle = grass;
828:     ctx.fillRect(0, grassTop, W, Math.max(0, grassBottom - grassTop));
829:     // mowing stripes
830:     ctx.save();
831:     ctx.beginPath(); ctx.rect(0, grassTop, W, Math.max(0, grassBottom - grassTop)); ctx.clip();
832:     const stripeW = Math.max(50, W * 0.075);
833:     for (let i = -2; i < W / stripeW + 2; i++) {
834:       if (i % 2 === 0) {
835:         ctx.fillStyle = winter ? 'rgba(196,238,255,.035)' : 'rgba(74,158,109,.045)';
836:         ctx.fillRect(i * stripeW + (this.camX * 3) % (stripeW * 2), grassTop, stripeW, grassBottom - grassTop);
837:       }
838:     }
839:     // little mow arrows / snow drifts
840:     ctx.globalAlpha = winter ? 0.07 : 0.05;
841:     ctx.strokeStyle = winter ? '#dff4ff' : '#b8ffd9';
842:     ctx.lineWidth = 1;
843:     for (let x = -100; x < W + 100; x += 170) {
844:       const y = grassTop + (grassBottom - grassTop) * 0.55;
845:       ctx.beginPath(); ctx.moveTo(x, y); ctx.lineTo(x + 60, y); ctx.stroke();
846:     }
847:     ctx.restore();
848: 
849:     // banner boards at the back of the track
850:     this.drawAdBoards(ctx, mode, L);
851: 
852:     if (winter && mode === 'curling') {
853:       this.drawCurlingSheet(ctx, L);
854:       return;
855:     }
856:     if (winter && mode === 'skijump') {
857:       this.drawSkiJumpHill(ctx, L);
858:       return;
859:     }
860:     if (mode === 'longjump') {
861:       this.drawRunway(ctx, L, 'longjump');
862:       return;
863:     }
864:     if (mode === 'javelin') {
865:       this.drawRunway(ctx, L, 'javelin');
866:       this.drawJavelinField(ctx, L);
867:       return;
868:     }
869:     this.drawSprintTrack(ctx, L, mode);
870:   }
871: 
872:   drawAdBoards(ctx, mode, L) {
873:     const W = this.W;
874:     const y = H_(this.H, 0.575);
875:     const h = Math.max(16, this.H * 0.024);
876:     const labels = this.season === 'winter'
877:       ? ['OLYMPIA', 'WINTER SERIES', 'SNOW & ICE', 'SAPPORO 26', 'NIGHT SESSION', 'OLYMPIA']
878:       : ['OLYMPIA', 'GOLD SERIES', 'TRACK & FIELD', 'PARIS 26', 'NIGHT SESSION', 'OLYMPIA'];
879:     const panelW = 155 * this.u;
880:     const startWorld = Math.floor((this.camX - 20) / 20) * 20;
881:     for (let xw = startWorld; xw < this.camX + (W / this.meter) + 40; xw += 20) {
882:       const idx = Math.abs(Math.round(xw / 20)) % labels.length;
883:       const x = this.sx(xw);
884:       const yTop = y - h;
885:       ctx.save();
886:       ctx.globalAlpha = 0.9;
887:       const g = ctx.createLinearGradient(x, yTop, x, yTop + h);
888:       g.addColorStop(0, 'rgba(12,23,40,.92)');
889:       g.addColorStop(1, 'rgba(4,9,17,.97)');
890:       ctx.fillStyle = g;
891:       ctx.fillRect(x, yTop, panelW, h);
892:       ctx.strokeStyle = 'rgba(118,153,190,.22)';
893:       ctx.lineWidth = 0.7;
894:       ctx.strokeRect(x, yTop, panelW, h);
895:       // lit sponsor strip
896:       ctx.fillStyle = idx % 3 === 0 ? 'rgba(247,201,80,.06)' : 'rgba(104,219,255,.045)';
897:       ctx.fillRect(x, yTop, panelW, h);
898:       ctx.fillStyle = idx % 3 === 0 ? 'rgba(247,201,80,.86)' : 'rgba(239,244,250,.72)';
899:       ctx.font = `700 ${Math.max(7, h * 0.38)}px "Barlow Condensed", sans-serif`;
900:       ctx.textAlign = 'center';
901:       ctx.textBaseline = 'middle';
902:       ctx.fillText(labels[idx], x + panelW / 2, yTop + h * 0.54);
903:       ctx.fillStyle = 'rgba(247,201,80,.55)';
904:       ctx.fillRect(x, yTop + h - 2, panelW, 1.2);
905:       ctx.restore();
906:     }
907:   }
908: 
909:   drawSprintTrack(ctx, L, mode) {
910:     const W = this.W, H = this.H;
911:     const top = L.top, bottom = L.bottom;
912:     const winter = this.season === 'winter';
913:     const base = ctx.createLinearGradient(0, top, 0, bottom);
914:     if (winter) {
915:       base.addColorStop(0, '#9fc7d8');
916:       base.addColorStop(0.18, '#c4e0ec');
917:       base.addColorStop(0.5, '#dbedf4');
918:       base.addColorStop(0.82, '#b7d8e6');
919:       base.addColorStop(1, '#7fa8bd');
920:     } else {
921:       base.addColorStop(0, '#5a221d');
922:       base.addColorStop(0.18, '#7d3025');
923:       base.addColorStop(0.58, '#9c3c2a');
924:       base.addColorStop(1, '#6e271f');
925:     }
926:     ctx.fillStyle = base;
927:     ctx.fillRect(0, top, W, bottom - top);
928: 
929:     // Broad pools of floodlight sheen running across the rubber.
930:     ctx.save();
931:     ctx.globalCompositeOperation = 'screen';
932:     const sheen = ctx.createLinearGradient(0, top, 0, bottom);
933:     if (winter) {
934:       sheen.addColorStop(0, 'rgba(210,244,255,.04)');
935:       sheen.addColorStop(0.5, 'rgba(235,252,255,.16)');
936:       sheen.addColorStop(1, 'rgba(190,235,255,.03)');
937:     } else {
938:       sheen.addColorStop(0, 'rgba(255,213,168,.02)');
939:       sheen.addColorStop(0.5, 'rgba(255,225,185,.11)');
940:       sheen.addColorStop(1, 'rgba(255,190,140,.02)');
941:     }
942:     ctx.fillStyle = sheen;
943:     for (let i = -1; i < 4; i++) {
944:       const x = ((W * (0.14 + i * 0.27) - this.camX * this.meter * 0.22) % (W * 1.1)) - W * 0.2;
945:       ctx.beginPath();
946:       ctx.ellipse(x, top + (bottom - top) * 0.58, W * 0.16, (bottom - top) * 0.52, -0.06, 0, TAU);
947:       ctx.fill();
948:     }
949:     ctx.restore();
950: 
951:     const playerLane = this.playerLane ?? 3;
952:     for (let i = 0; i < L.laneCount; i++) {
953:       const y = top + i * L.laneH;
954:       if (i === playerLane && (mode === 'sprint')) {
955:         ctx.fillStyle = winter ? 'rgba(143,228,255,.1)' : 'rgba(247,201,80,.045)';
956:         ctx.fillRect(0, y, W, L.laneH);
957:       } else if (i % 2 === 0) {
958:         ctx.fillStyle = winter ? 'rgba(255,255,255,.05)' : 'rgba(255,150,110,.028)';
959:         ctx.fillRect(0, y, W, L.laneH);
960:       }
961:       // lane line
962:       ctx.strokeStyle = winter ? 'rgba(58,96,120,.42)' : 'rgba(240,232,214,.6)';
963:       ctx.lineWidth = Math.max(0.7, 1.2 * this.u);
964:       ctx.beginPath(); ctx.moveTo(0, y); ctx.lineTo(W, y); ctx.stroke();
965:       // inner shadow on the line
966:       ctx.strokeStyle = winter ? 'rgba(255,255,255,.35)' : 'rgba(60,10,8,.35)';
967:       ctx.lineWidth = 1;
968:       ctx.beginPath(); ctx.moveTo(0, y + 1.6); ctx.lineTo(W, y + 1.6); ctx.stroke();
969:       // lane number painted on the rubber near the start
970:       if (mode === 'sprint' && !winter) {
971:         const nx = this.sx(2.6);
972:         if (nx > -30 && nx < W + 30) {
973:           ctx.save();
974:           ctx.globalAlpha = 0.34;
975:           ctx.fillStyle = '#f8efdb';
976:           ctx.font = `700 ${Math.max(8, L.laneH * 0.3)}px "Barlow Condensed", sans-serif`;
977:           ctx.textAlign = 'center';
978:           ctx.textBaseline = 'middle';
979:           ctx.fillText(String(i + 1), nx, y + L.laneH * 0.52);
980:           ctx.restore();
981:         }
982:       }
983:     }
984:     // outer edge
985:     ctx.strokeStyle = winter ? 'rgba(46,84,108,.45)' : 'rgba(240,232,214,.5)';
986:     ctx.lineWidth = 1.4;
987:     ctx.beginPath(); ctx.moveTo(0, bottom); ctx.lineTo(W, bottom); ctx.stroke();
988: 
989:     // noise + light pools
990:     ctx.save();
991:     ctx.globalAlpha = winter ? 0.12 : 0.32;
992:     const pattern = ctx.createPattern(this.trackNoise, 'repeat');
993:     ctx.fillStyle = pattern;
994:     ctx.fillRect(0, top, W, bottom - top);
995:     ctx.restore();
996: 
997:     if (winter) {
998:       // snow banks framing the course
999:       for (const edge of [top, bottom]) {
1000:         const bank = ctx.createLinearGradient(0, edge - 12, 0, edge + 12);
1001:         bank.addColorStop(0, 'rgba(226,245,255,0)');
1002:         bank.addColorStop(0.5, 'rgba(230,247,255,.5)');
1003:         bank.addColorStop(1, 'rgba(180,219,236,0)');
1004:         ctx.fillStyle = bank;
1005:         ctx.fillRect(0, edge - 12, W, 24);
1006:       }
1007:       this.drawSnowboardGates(ctx, L, mode);
1008:     }
1009: 
1010:     ctx.save();
1011:     ctx.globalCompositeOperation = 'screen';
1012:     for (let i = 0; i < 4; i++) {
1013:       const x = W * (0.1 + i * 0.28) + Math.sin(this.t * 0.1 + i) * 25;
1014:       const g = ctx.createRadialGradient(x, top + (bottom - top) * 0.55, 0, x, top + (bottom - top) * 0.55, W * 0.22);
1015:       g.addColorStop(0, winter ? 'rgba(198,241,255,.07)' : 'rgba(255,213,157,.035)');
1016:       g.addColorStop(1, 'rgba(255,213,157,0)');
1017:       ctx.fillStyle = g;
1018:       ctx.fillRect(0, top, W, bottom - top);
1019:     }
1020:     ctx.restore();
1021: 
1022:     // world markings
1023:     this.drawTrackMarks(ctx, L, mode);
1024: 
1025:     // start blocks
1026:     if (!winter) for (let i = 0; i < L.laneCount; i++) {
1027:       const x = this.sx(-1.5);
1028:       const y = this.groundY(i, mode) + 1;
1029:       const w = Math.max(16, this.meter * 1.15);
1030:       const bs = 0.82 + (i / Math.max(1, L.laneCount - 1)) * 0.24;
1031:       ctx.save();
1032:       ctx.translate(x, y);
1033:       ctx.scale(bs, bs);
1034:       // ground shadow
1035:       ctx.fillStyle = 'rgba(0,0,0,.35)';
1036:       ctx.beginPath(); ctx.ellipse(-w * 0.05, 1.5, w * 0.85, 3.2, 0, 0, TAU); ctx.fill();
1037:       // base rail
1038:       ctx.fillStyle = '#101a29';
1039:       ctx.strokeStyle = 'rgba(190,208,232,.22)';
1040:       ctx.lineWidth = 0.8;
1041:       ctx.beginPath();
1042:       ctx.moveTo(-w * 0.62, 0); ctx.lineTo(w * 0.34, 0);
1043:       ctx.lineTo(w * 0.28, -3); ctx.lineTo(-w * 0.58, -3);
1044:       ctx.closePath(); ctx.fill(); ctx.stroke();
1045:       // pedal one
1046:       ctx.fillStyle = '#182436';
1047:       ctx.strokeStyle = 'rgba(247,201,80,.62)';
1048:       ctx.beginPath();
1049:       ctx.moveTo(-w * 0.5, -2); ctx.lineTo(-w * 0.16, -13);
1050:       ctx.lineTo(-w * 0.06, -9); ctx.lineTo(-w * 0.4, 2);
1051:       ctx.closePath(); ctx.fill(); ctx.stroke();
1052:       // pedal two
1053:       ctx.beginPath();
1054:       ctx.moveTo(-w * 0.02, -2); ctx.lineTo(w * 0.32, -17);
1055:       ctx.lineTo(w * 0.42, -13); ctx.lineTo(w * 0.1, 2);
1056:       ctx.closePath(); ctx.fill(); ctx.stroke();
1057:       // grip stripes
1058:       ctx.strokeStyle = 'rgba(255,255,255,.16)';
1059:       ctx.lineWidth = 0.7;
1060:       for (let k = 0; k < 3; k++) {
1061:         ctx.beginPath();
1062:         ctx.moveTo(-w * 0.13 + k * 8, -11 + k * 2.2);
1063:         ctx.lineTo(-w * 0.02 + k * 8, -8 + k * 2.2);
1064:         ctx.stroke();
1065:       }
1066:       ctx.restore();
1067:     }
1068:   }
1069: 
1070:   drawSnowboardGates(ctx, L, mode) {
1071:     if (mode !== 'sprint') return;
1072:     const gates = [18, 37, 56, 75, 92];
1073:     for (let gi = 0; gi < gates.length; gi++) {
1074:       const x = this.sx(gates[gi]);
1075:       if (x < -30 || x > this.W + 30) continue;
1076:       const warm = gi % 2 === 0;
1077:       for (let lane = 0; lane < L.laneCount; lane++) {
1078:         const y = this.groundY(lane, mode);
1079:         const s = 0.8 + lane / L.laneCount * 0.3;
1080:         ctx.save();
1081:         ctx.globalAlpha = lane === this.playerLane ? 1 : 0.7;
1082:         ctx.fillStyle = warm ? '#ff6a4d' : '#59c8ff';
1083:         ctx.beginPath();
1084:         ctx.moveTo(x, y - 2);
1085:         ctx.lineTo(x, y - 18 * s);
1086:         ctx.lineTo(x + 11 * s, y - 12 * s);
1087:         ctx.closePath();
1088:         ctx.fill();
1089:         ctx.strokeStyle = 'rgba(255,255,255,.6)';
1090:         ctx.lineWidth = 0.7;
1091:         ctx.stroke();
1092:         ctx.fillStyle = 'rgba(255,255,255,.75)';
1093:         ctx.fillRect(x - 1, y - 20 * s, 1.4, 20 * s);
1094:         ctx.restore();
1095:       }
1096:     }
1097:   }
1098: 
1099:   drawSkiJumpHill(ctx, L) {
1100:     const W = this.W, H = this.H;
1101:     const top = L.top - L.laneH * 0.1;
1102:     const bottom = L.bottom;
1103:     const gy = this.groundY(1, 'skijump');
1104:     const snow = ctx.createLinearGradient(0, top, 0, bottom);
1105:     snow.addColorStop(0, '#c6e3ef');
1106:     snow.addColorStop(0.45, '#e6f5fb');
1107:     snow.addColorStop(1, '#a8cde0');
1108:     ctx.fillStyle = snow;
1109:     ctx.fillRect(0, top, W, bottom - top + H * 0.16);
1110: 
1111:     // distance arcs across the outrun
1112:     ctx.save();
1113:     for (let m = 50; m <= 150; m += 10) {
1114:       const x = this.sx(40.5 + m);
1115:       if (x < -30 || x > W + 30) continue;
1116:       ctx.strokeStyle = m % 50 === 0 ? 'rgba(43,113,150,.4)' : 'rgba(43,113,150,.18)';
1117:       ctx.lineWidth = m % 50 === 0 ? 1.3 : 0.7;
1118:       ctx.beginPath();
1119:       ctx.moveTo(x, gy - 4);
1120:       ctx.lineTo(x, bottom + H * 0.1);
1121:       ctx.stroke();
1122:       if (m % 50 === 0) {
1123:         ctx.fillStyle = 'rgba(28,78,104,.6)';
1124:         ctx.font = `700 ${Math.max(7, H * 0.011)}px "Barlow Condensed", sans-serif`;
1125:         ctx.textAlign = 'center';
1126:         ctx.fillText(`${m}M`, x, bottom + H * 0.055);
1127:       }
1128:     }
1129:     ctx.restore();
1130: 
1131:     // inrun ramp and takeoff lip
1132:     const lipX = this.sx(40.5);
1133:     const startX = this.sx(30);
1134:     ctx.save();
1135:     const ramp = ctx.createLinearGradient(0, gy - 18, 0, gy + 4);
1136:     ramp.addColorStop(0, '#f2fbff');
1137:     ramp.addColorStop(1, '#9cc4d6');
1138:     ctx.fillStyle = ramp;
1139:     ctx.beginPath();
1140:     ctx.moveTo(startX, gy + 2);
1141:     ctx.lineTo(lipX, gy - 5);
1142:     ctx.lineTo(lipX, gy + 3);
1143:     ctx.closePath();
1144:     ctx.fill();
1145:     ctx.strokeStyle = 'rgba(20,60,84,.5)';
1146:     ctx.lineWidth = 0.9;
1147:     ctx.stroke();
1148:     // takeoff markers
1149:     ctx.fillStyle = '#f7c950';
1150:     ctx.fillRect(lipX - 2, gy - 9, 4, 12);
1151:     ctx.strokeStyle = 'rgba(247,201,80,.55)';
1152:     ctx.lineWidth = 1;
1153:     ctx.beginPath(); ctx.moveTo(lipX, gy - 12); ctx.lineTo(lipX, gy + 8); ctx.stroke();
1154:     ctx.fillStyle = 'rgba(28,78,104,.7)';
