242: function limb(ctx, a, b, width, color, dark, light) {
243:   ctx.lineCap = 'round';
244:   ctx.lineJoin = 'round';
245:   ctx.strokeStyle = dark;
246:   ctx.lineWidth = width + 1.9;
247:   ctx.beginPath(); ctx.moveTo(a.x, a.y); ctx.lineTo(b.x, b.y); ctx.stroke();
248:   ctx.strokeStyle = color;
249:   ctx.lineWidth = width;
250:   ctx.beginPath(); ctx.moveTo(a.x, a.y); ctx.lineTo(b.x, b.y); ctx.stroke();
251:   if (light) {
252:     ctx.strokeStyle = light;
253:     ctx.lineWidth = Math.max(1, width * 0.2);
254:     ctx.globalAlpha *= 0.8;
255:     ctx.beginPath();
256:     ctx.moveTo(a.x + width * 0.2, a.y - width * 0.18);
257:     ctx.lineTo(b.x + width * 0.18, b.y - width * 0.16);
258:     ctx.stroke();
259:     ctx.globalAlpha /= 0.8;
260:   }
261: }
