263: function drawShoe(ctx, leg, kit, alpha = 1) {
264:   const { ankle, toe, footA } = leg;
265:   const dx = Math.sin(footA), dy = Math.cos(footA);
266:   const nx = -dy, ny = dx;
267:   const heel = { x: ankle.x - dx * 4.5, y: ankle.y - dy * 4.5 };
268:   const tip = { x: toe.x + dx * 1.8, y: toe.y + dy * 1.8 };
269:   ctx.globalAlpha *= alpha;
270:   ctx.beginPath();
271:   ctx.moveTo(heel.x + nx * 4.3, heel.y + ny * 4.3);
272:   ctx.quadraticCurveTo(tip.x + nx * 3.2, tip.y + ny * 3.2, tip.x, tip.y);
273:   ctx.lineTo(heel.x - nx * 3.4, heel.y - ny * 3.4);
274:   ctx.closePath();
275:   ctx.fillStyle = kit.shoe;
276:   ctx.fill();
277:   ctx.strokeStyle = shade(kit.shoe, -0.48);
278:   ctx.lineWidth = 1;
279:   ctx.stroke();
280:   ctx.beginPath();
281:   ctx.moveTo(heel.x + nx * 2.2, heel.y + ny * 2.2);
282:   ctx.quadraticCurveTo(tip.x + nx * 2.2, tip.y + ny * 2.2, tip.x, tip.y);
283:   ctx.strokeStyle = 'rgba(255,255,255,.82)';
284:   ctx.lineWidth = 1.15;
285:   ctx.stroke();
286:   ctx.globalAlpha /= alpha;
287: }
