321: function drawTorso(ctx, sk, kit) {
322:   const hip = sk.hip, chest = sk.chest;
323:   const dx = chest.x - hip.x, dy = chest.y - hip.y;
324:   const len = Math.hypot(dx, dy) || 1;
325:   const nx = -dy / len, ny = dx / len;
326:   const hipW = 7.3, chestW = 11.5;
327:   const hipL = { x: hip.x + nx * hipW, y: hip.y + ny * hipW };
328:   const hipR = { x: hip.x - nx * hipW, y: hip.y - ny * hipW };
329:   const chestL = { x: chest.x + nx * chestW, y: chest.y + ny * chestW };
330:   const chestR = { x: chest.x - nx * chestW, y: chest.y - ny * chestW };
331: 
332:   // shorts
333:   ctx.beginPath();
334:   ctx.moveTo(hipL.x - 1, hipL.y - 1);
335:   ctx.quadraticCurveTo(hip.x - 11, hip.y + 8, hipL.x - 4, hip.y + 15);
336:   ctx.lineTo(hipL.x + 7, hip.y + 16);
337:   ctx.quadraticCurveTo(hip.x + 7, hip.y + 6, hipR.x + 7, hipR.y + 1);
338:   ctx.closePath();
339:   ctx.fillStyle = kit.primary;
340:   ctx.fill();
341: 
342:   // jersey
343:   ctx.beginPath();
344:   ctx.moveTo(hipR.x, hipR.y);
345:   ctx.quadraticCurveTo(hip.x - 10, (hip.y + chest.y) / 2, chestR.x - 2, chestR.y + 3);
346:   ctx.quadraticCurveTo(chest.x - 2, chest.y - 6, chestL.x + 1, chestL.y);
347:   ctx.quadraticCurveTo(chest.x + 12, (hip.y + chest.y) / 2, hipL.x + 2, hipL.y + 2);
348:   ctx.closePath();
349:   ctx.fillStyle = kit.primary;
350:   ctx.fill();
351:   ctx.strokeStyle = shade(kit.primary, -0.4);
352:   ctx.lineWidth = 0.8;
353:   ctx.stroke();
354: 
355:   // chest stripe
356:   ctx.save();
357:   ctx.clip();
358:   ctx.strokeStyle = kit.secondary;
359:   ctx.lineWidth = 5;
360:   ctx.beginPath();
361:   ctx.moveTo(chest.x - 18, chest.y + 7);
362:   ctx.lineTo(chest.x + 18, chest.y - 5);
363:   ctx.stroke();
364:   ctx.strokeStyle = rgba(kit.accent, 0.9);
365:   ctx.lineWidth = 1.1;
366:   ctx.beginPath();
367:   ctx.moveTo(chest.x - 18, chest.y + 10);
368:   ctx.lineTo(chest.x + 18, chest.y - 2);
369:   ctx.stroke();
370:   ctx.restore();
371: 
372:   // side stripe
373:   ctx.strokeStyle = rgba(kit.secondary, 0.85);
374:   ctx.lineWidth = 1.5;
375:   ctx.beginPath();
376:   ctx.moveTo(hipR.x - 1, hipR.y - 1);
377:   ctx.quadraticCurveTo(hip.x - 7, (hip.y + chest.y) / 2, chestR.x - 1, chestR.y + 4);
378:   ctx.stroke();
379: 
380:   // bib
381:   ctx.save();
382:   ctx.translate(chest.x + 2, chest.y + 14);
383:   ctx.rotate(sk.lean * 0.7);
384:   ctx.fillStyle = 'rgba(247,244,234,.92)';
385:   ctx.fillRect(-5.5, -4, 11, 8.5);
386:   ctx.fillStyle = '#101828';
387:   ctx.font = '600 6.5px "Barlow Condensed", sans-serif';
388:   ctx.textAlign = 'center';
389:   ctx.textBaseline = 'middle';
390:   ctx.fillText('7', 0, 0.4);
391:   ctx.restore();
392: 
393:   // shorts trim
394:   ctx.strokeStyle = rgba(kit.accent, 0.88);
395:   ctx.lineWidth = 1.1;
396:   ctx.beginPath();
397:   ctx.moveTo(hipL.x - 3, hip.y + 8);
398:   ctx.quadraticCurveTo(hip.x, hip.y + 13, hipR.x + 3, hip.y + 7);
399:   ctx.stroke();
400: 
401:   // rim light along back/upper torso
402:   ctx.strokeStyle = rgba(kit.trim || '#ffffff', 0.62);
403:   ctx.lineWidth = 1.25;
404:   ctx.beginPath();
405:   ctx.moveTo(chestL.x, chestL.y + 2);
406:   ctx.quadraticCurveTo(chest.x + 11, chest.y + 12, hipL.x - 1, hip.y - 2);
407:   ctx.stroke();
408: 
409:   // subtle chest shadow
410:   ctx.strokeStyle = 'rgba(0,0,0,.18)';
411:   ctx.lineWidth = 4;
412:   ctx.beginPath();
413:   ctx.moveTo(chestR.x + 3, chestR.y + 7);
414:   ctx.quadraticCurveTo(chest.x - 4, (hip.y + chest.y) / 2, hipR.x + 3, hipR.y - 2);
415:   ctx.stroke();
416: }
