418: function drawHead(ctx, sk, kit, phase) {
419:   const head = sk.head;
420:   const r = 9.2;
421:   // neck
422:   ctx.strokeStyle = kit.skinDark;
423:   ctx.lineWidth = 5.8;
424:   ctx.lineCap = 'round';
425:   ctx.beginPath();
426:   ctx.moveTo(sk.neck.x, sk.neck.y + 1);
427:   ctx.lineTo(head.x - 3, head.y + r * 0.7);
428:   ctx.stroke();
429:   ctx.strokeStyle = kit.skin;
430:   ctx.lineWidth = 4.5;
431:   ctx.beginPath();
432:   ctx.moveTo(sk.neck.x, sk.neck.y);
433:   ctx.lineTo(head.x - 3, head.y + r * 0.6);
434:   ctx.stroke();
435: 
436:   // ear
437:   ctx.fillStyle = kit.skinDark;
438:   ctx.beginPath(); ctx.ellipse(head.x - 4.5, head.y + 1, 2.4, 3.2, -0.2, 0, TAU); ctx.fill();
439: 
440:   // head shape (slight forward jaw)
441:   ctx.beginPath();
442:   ctx.ellipse(head.x, head.y, r * 0.94, r, 0.08, 0, TAU);
443:   ctx.fillStyle = kit.skin;
444:   ctx.fill();
445: 
446:   // jaw shading
447:   ctx.beginPath();
448:   ctx.ellipse(head.x + 1.5, head.y + 3.4, 6.7, 6.1, 0.1, 0.2, Math.PI * 1.02);
449:   ctx.fillStyle = rgba(kit.skinDark, 0.25);
450:   ctx.fill();
451: 
452:   // nose
453:   ctx.beginPath();
454:   ctx.moveTo(head.x + 7.6, head.y - 1.5);
455:   ctx.quadraticCurveTo(head.x + 10, head.y + 1.6, head.x + 7.3, head.y + 3.2);
456:   ctx.lineTo(head.x + 6.4, head.y + 2.2);
457:   ctx.closePath();
458:   ctx.fillStyle = kit.skin;
459:   ctx.fill();
460: 
461:   // hair
462:   ctx.beginPath();
463:   ctx.arc(head.x - 1, head.y - 1.2, r * 1.02, Math.PI * 0.68, Math.PI * 2.02);
464:   ctx.quadraticCurveTo(head.x + 2, head.y - 8.2, head.x + 4, head.y - 5.2);
465:   ctx.quadraticCurveTo(head.x - 1, head.y - 5.7, head.x - 7.2, head.y + 3.3);
466:   ctx.closePath();
467:   ctx.fillStyle = kit.hair;
468:   ctx.fill();
469:   // hair sheen
470:   ctx.strokeStyle = 'rgba(255,255,255,.2)';
471:   ctx.lineWidth = 0.8;
472:   ctx.beginPath();
473:   ctx.arc(head.x - 2, head.y - 2.2, r * 0.78, Math.PI * 0.9, Math.PI * 1.5);
474:   ctx.stroke();
475: 
476:   // headband
477:   if (kit.trim) {
478:     ctx.strokeStyle = rgba(kit.trim, 0.9);
479:     ctx.lineWidth = 2.1;
480:     ctx.beginPath();
481:     ctx.arc(head.x - 0.5, head.y - 1.2, r * 0.87, Math.PI * 1.08, Math.PI * 1.87);
482:     ctx.stroke();
483:   }
484: 
485:   // features
486:   ctx.fillStyle = '#15100e';
487:   ctx.beginPath();
488:   ctx.ellipse(head.x + 4.6, head.y - 0.8, 1.15, 0.9, 0.15, 0, TAU);
489:   ctx.fill();
490:   ctx.strokeStyle = 'rgba(36,18,10,.75)';
491:   ctx.lineWidth = 0.75;
492:   ctx.beginPath();
493:   ctx.moveTo(head.x + 2.6, head.y - 3.4);
494:   ctx.lineTo(head.x + 6.9, head.y - 2.7);
495:   ctx.stroke();
496:   ctx.strokeStyle = 'rgba(80,35,25,.6)';
497:   ctx.lineWidth = 0.8;
498:   ctx.beginPath();
499:   ctx.moveTo(head.x + 6.2, head.y + 5.1);
500:   ctx.quadraticCurveTo(head.x + 7.5, head.y + 5.4, head.x + 7.8, head.y + 4.7);
501:   ctx.stroke();
502: }
