520: function drawSnowboard(ctx, sk, kit) {
521:   const feet = (sk.legs || []).map(l => l.ankle);
522:   if (!feet.length) return;
523:   const y = Math.max(...feet.map(f => f.y)) + 4;
524:   const cx = feet.reduce((a, f) => a + f.x, 0) / feet.length;
525:   ctx.save();
526:   ctx.translate(cx, y);
527:   ctx.rotate(-0.045 + Math.sin((sk.phase || 0) * 0.9) * 0.02);
528:   const len = 46, h = 5;
529:   const g = ctx.createLinearGradient(-len / 2, 0, len / 2, 0);
530:   g.addColorStop(0, '#111d31');
531:   g.addColorStop(0.35, kit.accent || '#49b9e6');
532:   g.addColorStop(0.7, '#2b7196');
533:   g.addColorStop(1, '#0b1422');
534:   ctx.fillStyle = g;
535:   ctx.beginPath();
536:   ctx.moveTo(-len / 2, -h / 2);
537:   ctx.quadraticCurveTo(-len / 2 - 5, -h / 2 - 3, -len / 2 - 4, -1);
538:   ctx.quadraticCurveTo(-len / 2 - 2, h / 2 + 2, -len / 2 + 4, h / 2);
539:   ctx.lineTo(len / 2 - 3, h / 2);
540:   ctx.quadraticCurveTo(len / 2 + 5, h / 2 + 1, len / 2 + 5, -1);
541:   ctx.quadraticCurveTo(len / 2 + 3, -h / 2 - 3, len / 2 - 4, -h / 2);
542:   ctx.closePath();
543:   ctx.fill();
544:   ctx.strokeStyle = 'rgba(220,246,255,.55)';
545:   ctx.lineWidth = 0.8;
546:   ctx.stroke();
547:   ctx.fillStyle = 'rgba(255,255,255,.2)';
548:   ctx.fillRect(-len * 0.22, -h / 2 + 1, len * 0.44, 1);
549:   ctx.restore();
550: }
