554:     ctx.save();
555:     ctx.translate(leg.ankle.x, leg.ankle.y + 4);
556:     ctx.rotate(-0.05);
557:     const len = 46, h = 3.4;
558:     const g = ctx.createLinearGradient(-len / 2, 0, len / 2, 0);
559:     g.addColorStop(0, '#d8e8f4');
560:     g.addColorStop(0.4, kit.primary || '#e33a4a');
561:     g.addColorStop(1, '#f4f9ff');
562:     ctx.fillStyle = g;
563:     ctx.beginPath();
564:     ctx.moveTo(-len / 2, -h / 2);
565:     ctx.lineTo(len / 2 - 6, -h / 2);
566:     ctx.quadraticCurveTo(len / 2 + 7, -h / 2 - 3, len / 2 + 8, -h / 2 - 7);
567:     ctx.lineTo(len / 2 + 6, -h / 2 - 1);
568:     ctx.lineTo(-len / 2, h / 2);
569:     ctx.closePath();
570:     ctx.fill();
571:     ctx.strokeStyle = 'rgba(20,32,48,.5)';
572:     ctx.lineWidth = 0.7;
573:     ctx.stroke();
574:     // binding
575:     ctx.fillStyle = '#101a28';
576:     ctx.fillRect(-3, -h / 2 - 2, 6, 3);
577:     ctx.restore();
578:   }
579: }
