581: export function drawAthlete(ctx, opts) {
582:   const {
583:     x = 0, y = 0, scale = 1, phase = 0, pose = 'run', speed = 0.6,
584:     kit = KITS.player, flip = false, alpha = 1, shadow = 1, javelin = null,
585:     glow = 0, medal = false, skis = false, board = false
586:   } = opts;
587:   const sk = makeSkeleton(pose, phase, speed);
588:   const s = scale * (flip ? -1 : 1);
589:   const bob = pose === 'run' ? Math.sin(phase * 2 + 0.15) : 0;
590: 
591:   ctx.save();
592:   ctx.globalAlpha *= alpha;
593:   ctx.translate(x, y);
594:   if (shadow) {
595:     ctx.save();
596:     ctx.translate(0, 1.5);
597:     ctx.scale(1, 0.24);
598:     const grad = ctx.createRadialGradient(0, 0, 1, 0, 0, 32);
599:     grad.addColorStop(0, 'rgba(0,0,0,.42)');
600:     grad.addColorStop(0.65, 'rgba(0,0,0,.19)');
601:     grad.addColorStop(1, 'rgba(0,0,0,0)');
602:     ctx.fillStyle = grad;
603:     ctx.beginPath(); ctx.arc(0, 0, 32 * shadow, 0, TAU); ctx.fill();
604:     ctx.restore();
605:   }
606:   ctx.scale(s, scale);
607:   ctx.translate(0, bob);
608:   if (glow > 0) {
609:     ctx.shadowColor = rgba(kit.trim || '#f6cc58', 0.7 * glow);
610:     ctx.shadowBlur = 18 * glow;
611:   }
612: 
613:   if (sk.medal || medal) drawMedal(ctx, kit);
614: 
615:   if (board) drawSnowboard(ctx, sk, kit);
616:   if (skis) drawSkis(ctx, sk, kit);
