481:   onKey(e) {
482:     const key = e.key;
483:     const lower = key.toLowerCase();
484:     this.sound.init();
485:     if (key === 'Escape') {
486:       if (document.getElementById('guide').classList.contains('is-active')) { this.closeGuide(); return; }
487:       if (this.paused) { this.resume(); return; }
488:       if (this.state === 'running') { this.openPause(); return; }
489:       if (document.getElementById('practiceMenu').classList.contains('is-active')) {
490:         document.getElementById('practiceMenu').classList.remove('is-active');
491:       }
492:       return;
493:     }
494:     if (this.paused && (lower === 'r')) { this.restartEvent(); return; }
495:     if (this.state === 'running' && this.currentEvent) {
496:       if (EVENTS[this.currentEventId]?.hud === 'sprint') {
497:         if (lower === 'a' || key === 'ArrowLeft') { e.preventDefault(); this.handleDirectional('left'); }
498:         if (lower === 'd' || key === 'ArrowRight') { e.preventDefault(); this.handleDirectional('right'); }
499:       } else if (key === ' ' || lower === 'j') {
500:         e.preventDefault();
501:         if (!e.repeat) this.handleAction();
502:       }
503:     } else if (this.state === 'countdown') {
504:       if (EVENTS[this.currentEventId]?.hud === 'sprint' && (lower === 'a' || lower === 'd' || key === 'ArrowLeft' || key === 'ArrowRight' || key === ' ')) {
505:         e.preventDefault();
506:         this.onFalseStartInput();
507:       }
508:     }
509:     if (key === ' ' && this.state === 'countdown') e.preventDefault();
510:   }
