757:     w.drawRoof(ctx);
758:     w.drawCrowd(ctx);
759:     w.drawJumbotron(ctx, { ...(opts.jumbo || {}), mode });
760:     w.drawLedRibbon(ctx, { ribbon: opts.ribbon });
761:     w.drawGround(ctx, { mode });
