797:   renderMenu() {
798:     const ctx = this.ctx;
799:     this.paintWorld('menu', {
800:       jumbo: { top: 'OLYMPIA', big: 'OLYMPIA', sub: this.season === 'winter' ? 'WINTER SESSION' : 'NIGHT SESSION', value: this.season === 'winter' ? 'SAPPORO' : '20:26' }
801:     });
802:     const portrait = this.W < 760;
803:     const hx = this.W * (portrait ? 0.75 : 0.61);
804:     const gy = this.H * (portrait ? 0.80 : 0.815);
805:     const scale = clamp(this.H * (portrait ? 0.00205 : 0.00255), 1.2, 2.45);
806:     this.world.drawSpotlight(ctx, hx, gy - this.H * 0.22, this.H * (portrait ? 0.32 : 0.42), 1.05);
807:     // eclipse ring
808:     ctx.save();
809:     ctx.globalCompositeOperation = 'screen';
810:     const ring = ctx.createRadialGradient(hx, gy - this.H * 0.24, this.H * 0.12, hx, gy - this.H * 0.24, this.H * 0.34);
811:     ring.addColorStop(0, 'rgba(255,214,122,0)');
812:     ring.addColorStop(0.82, 'rgba(255,205,100,.022)');
813:     ring.addColorStop(1, 'rgba(255,205,100,0)');
814:     ctx.fillStyle = ring;
815:     ctx.fillRect(hx - this.H * 0.4, gy - this.H * 0.62, this.H * 0.8, this.H * 0.8);
816:     ctx.restore();
817:     drawAthlete(ctx, {
818:       x: hx, y: gy, scale,
819:       phase: this.menuT * 0.78,
820:       pose: 'victory',
821:       speed: 0,
822:       kit: KITS.player,
823:       flip: true,
824:       glow: 0.4,
825:       shadow: 1.15
826:     });
827:     // A slim golden light rim on the floor.
828:     ctx.save();
829:     ctx.globalCompositeOperation = 'screen';
830:     const floor = ctx.createRadialGradient(hx, gy + 4, 0, hx, gy + 4, 110 * scale);
831:     floor.addColorStop(0, 'rgba(247,201,80,.12)');
832:     floor.addColorStop(1, 'rgba(247,201,80,0)');
833:     ctx.fillStyle = floor;
834:     ctx.beginPath(); ctx.ellipse(hx, gy + 4, 110 * scale, 13 * scale, 0, 0, TAU); ctx.fill();
835:     ctx.restore();
836:   }
