134:       p.taps++;
135:       p.lastSide = side;
136:       p.lastTap = t;
137:       this.game.sound.step(clamp(p.speed / 12, 0.2, 1));
138:       this.game.tapFlash(side);
139:       this.game.spawnParticle({
140:         x: this.game.W * 0.5 + rand(-60, 60),
141:         y: this.game.groundY(this.playerLane, 'sprint') - rand(4, 20),
142:         vx: rand(-30, 10), vy: rand(-20, -5), life: rand(0.2, 0.45),
143:         size: rand(1, 3), color: 'rgba(255,226,177,.32)', gravity: 8
144:       });
145:     } else {
146:       p.lastTap = t;
147:       p.speed *= 0.93;
148:     }
149:   }
150: 
151:   update(dt) {
152:     this.phase += dt;
153:     if (this.state !== 'running') return;
154:     this.raceTime += dt;
155: 
156:     const p = this.player;
157:     // Graceful fallback: nobody gets stuck at the start forever.
158:     if (!p.started && this.raceTime > 3.4) {
159:       p.started = true;
160:       p.auto = true;
161:       p.speed = 5.1;
162:       p.reaction = this.raceTime;
163:     }
164: 
165:     // Player physics: taps provide impulse, air / stride drag bleeds it away.
166:     if (p.started) {
167:       if (p.finished) {
168:         p.speed *= Math.exp(-2.4 * dt);
169:       } else {
170:         if (p.auto) p.speed = Math.max(p.speed, 5.1);
171:         p.speed *= Math.exp(-0.10 * dt);
172:         const prev = p.dist;
173:         p.dist += p.speed * this.distanceScale * dt;
174:         p.phase += p.speed * 1.06 * dt;
175:         this.checkHurdles(p, prev);
176:         if (p.dist >= this.raceDistance) {
177:           p.finished = true;
178:           p.time = this.raceTime - (p.dist - this.raceDistance) / Math.max(0.01, p.speed * this.distanceScale);
179:           p.dist = this.raceDistance;
180:           this.game.shake = Math.max(this.game.shake, 5);
181:           this.game.sound.cheer(1.1);
182:           this.game.toast(this.hurdleDistances ? 'CLEAN RUN' : 'FINISH', 'gold', 900);
183:         }
184:       }
185:     }
186: 
187:     for (const r of this.runners) {
188:       if (r.isPlayer || r.finished) continue;
189:       const speed = r.targetSpeed * smoothstep(0, 0.75, this.raceTime);
190:       r.speed = speed;
191:       const prev = r.dist;
192:       r.dist += speed * this.distanceScale * dt;
193:       r.phase += speed * 1.04 * dt;
194:       this.checkHurdles(r, prev);
195:       if (r.dist >= this.raceDistance) {
196:         r.finished = true;
197:         r.time = this.raceTime - (r.dist - this.raceDistance) / Math.max(0.01, speed * this.distanceScale);
198:         r.dist = this.raceDistance;
199:       }
200:     }
201: 
202:     const allDone = this.runners.every(r => r.finished);
203:     if (p.finished) {
204:       this.finishDelay += dt;
205:       if (allDone || this.finishDelay > 1.35) {
206:         this.state = 'done';
207:         this.done(p.time, { placeHint: this.liveRank });
208:         return;
209:       }
210:     }
211: 
212:     this.updateCamera(dt, p.dist, 1.1);
213:     this.updateLive(dt);
214:     this.spawnFootDust(dt);
215:   }
216: 
217:   checkHurdles(r, prevDist) {
218:     if (!this.hurdleDistances) return;
219:     for (let i = 0; i < this.hurdleDistances.length; i++) {
220:       const h = this.hurdleDistances[i];
221:       if (r.cleared[i] || prevDist >= h || r.dist < h) continue;
222:       r.cleared[i] = true;
223:       if (r.isPlayer) {
224:         if (r.speed < 10.2) {
225:           r.speed *= 0.86;
226:           this.game.shake = Math.max(this.game.shake, 3);
227:           this.game.toast('CLIPPED HURDLE', 'red', 760);
228:           this.game.sound.noise(0.14, 0.14, 'bandpass', 420);
229:         } else {
230:           this.game.burst(this.world.sx(h), this.game.groundY(this.playerLane, 'sprint') - 26, 5, 'rgba(255,232,190,.45)', 40, 0.35);
231:         }
232:         if (this.practice && i === 4) this.game.toast('HALFWAY — KEEP THE RHYTHM', 'gold', 700);
233:       }
234:     }
235:   }
236: 
237:   updateLive(dt) {
238:     const order = [...this.runners].sort((a, b) => {
239:       if (a.finished && b.finished) return a.time - b.time;
240:       return b.dist - a.dist;
241:     });
242:     this.liveRank = order.findIndex(r => r.isPlayer) + 1;
243:     this.game.setMiniBoard(
244:       order.map(r => ({
245:         id: r.athlete.id,
246:         name: r.athlete.name,
247:         code: r.athlete.code,
248:         player: r.isPlayer,
249:         value: r.finished ? fmtTime(r.time) : `${r.dist.toFixed(1)}m`
250:       })),
251:       'LIVE ORDER'
252:     );
253:     const next = this.player.lastSide === 'left' ? (this.game.touch ? 'R' : 'D') : (this.game.touch ? 'L' : 'A');
254:     const cadence = this.player.started ? clamp((this.player.speed - 4) / 8, 0, 1) : 0;
255:     this.hud({
256:       clock: fmtTime(this.raceTime),
257:       clockUnit: 's',
258:       clockLabel: 'RACE TIME',
259:       place: this.player.finished ? String(this.liveRank) : String(this.liveRank),
260:       meter: this.player.speed,
261:       meterMax: 13.2,
262:       meterUnit: 'M/S',
263:       meterLabel: 'VELOCITY',
264:       prompt: this.player.finished ? { visible: false } : {
265:         visible: true,
266:         key: next,
267:         title: this.player.started ? 'KEEP THE CADENCE' : 'EXPLODE FROM THE BLOCKS',
268:         sub: this.game.touch
269:           ? `Alternate ${this.player.lastSide === 'left' ? 'R' : 'L'} / ${next} — ${Math.round(this.player.speed * 10) / 10} m/s`
270:           : `Alternate ${this.player.lastSide === 'left' ? 'D' : 'A'} / ${next} — ${Math.round(this.player.speed * 10) / 10} m/s`,
271:         pulse: true
272:       },
273:       cadence,
274:       action: false
275:     });
276:   }
277: 
278:   spawnFootDust() {
279:     const p = this.player;
280:     if (!p.started || p.speed < 3.5) return;
281:     const crossed = Math.floor(p.phase / Math.PI);
282:     if (crossed !== this.lastPhase) {
283:       this.lastPhase = crossed;
284:       const x = this.world.sx(p.dist) - 12;
285:       const y = this.game.groundY(this.playerLane, 'sprint');
286:       for (let i = 0; i < 2; i++) {
287:         this.game.spawnParticle({
288:           x: x + rand(-12, 12), y: y - rand(0, 5),
289:           vx: rand(-50, -8), vy: rand(-34, -6), life: rand(0.28, 0.6),
290:           size: rand(1.4, 4.2),
291:           color: this.spray ? `rgba(220,244,255,${rand(0.2, 0.42)})` : `rgba(255,214,154,${rand(0.12, 0.27)})`,
292:           gravity: 26, drag: 0.5
293:         });
294:       }
295:     }
296:   }
297: 
298:   render(ctx) {
299:     this.world.playerLane = this.playerLane;
300:     this.paint();
301:     const order = [...this.runners].sort((a, b) => a.lane - b.lane);
302:     for (const r of order) {
303:       const x = this.world.sx(r.dist);
304:       if (x < -100 || x > this.W + 130) continue;
305:       const y = this.game.groundY(r.lane, 'sprint');
306:       const scale = this.world.laneScale(r.lane, 'sprint') * (r.isPlayer ? 1.03 : 1);
307:       let pose = 'run';
308:       if (this.state === 'ready' || this.game.state === 'countdown') pose = 'set';
309:       if (this.game.state === 'false-start') pose = 'set';
310:       if (r.finished && r.speed < 1.5) pose = 'idle';
311:       const nearHurdle = this.hurdleDistances?.some(h => Math.abs(r.dist - h) < 0.75 && !r.finished);
312:       if (nearHurdle) pose = 'jump';
313:       drawAthlete(ctx, {
314:         x, y, scale,
315:         phase: r.phase,
316:         pose,
317:         speed: clamp(r.speed / 12, 0, 1),
318:         kit: r.athlete.kit,
319:         glow: r.isPlayer ? 0.18 : 0.04,
320:         shadow: r.isPlayer ? 1.15 : 0.9,
321:         number: r.isPlayer ? 7 : 7,
322:         board: this.board
323:       });
324:       if (r.isPlayer && this.state !== 'ready') {
325:         this.drawPlayerTag(ctx, x, y, scale, r);
326:       }
327:     }
328:     this.drawHurdles(ctx);
329:     // Motion streaks for top speed.
330:     if (this.player.speed > 8.5) {
331:       const p = this.player;
332:       const x = this.world.sx(p.dist);
333:       const y = this.game.groundY(this.playerLane, 'sprint');
334:       ctx.save();
335:       ctx.globalCompositeOperation = 'screen';
336:       for (let i = 0; i < 7; i++) {
337:         const yy = y - 20 - i * 11 - rand(0, 8);
338:         const len = 28 + rand(0, 55) + p.speed * 2;
339:         const a = 0.018 + (p.speed - 8.5) * 0.013;
340:         const grad = ctx.createLinearGradient(x - len, yy, x + 12, yy);
341:         grad.addColorStop(0, 'rgba(255,236,185,0)');
342:         grad.addColorStop(0.7, `rgba(255,218,148,${a})`);
343:         grad.addColorStop(1, 'rgba(255,245,216,0)');
344:         ctx.strokeStyle = grad;
345:         ctx.lineWidth = 1 + rand(0, 1.7);
346:         ctx.beginPath(); ctx.moveTo(x - len, yy); ctx.lineTo(x + 20, yy); ctx.stroke();
347:       }
348:       ctx.restore();
349:     }
350:     this.drawFinishAtmosphere(ctx);
351:   }
352: 
353:   drawHurdles(ctx) {
354:     if (!this.hurdleDistances) return;
355:     for (const dist of this.hurdleDistances) {
356:       const x = this.world.sx(dist);
357:       if (x < -40 || x > this.W + 40) continue;
358:       for (let lane = 0; lane < 8; lane++) {
359:         const y = this.game.groundY(lane, 'sprint');
360:         const scale = this.world.laneScale(lane, 'sprint');
361:         const h = 30 * scale;
362:         const w = 15 * scale;
363:         ctx.save();
364:         ctx.globalAlpha = lane === this.playerLane ? 0.95 : 0.72;
365:         ctx.strokeStyle = lane === this.playerLane ? 'rgba(247,201,80,.9)' : 'rgba(226,236,248,.7)';
366:         ctx.lineWidth = 1.4 * scale;
367:         ctx.fillStyle = 'rgba(238,243,250,.82)';
368:         ctx.fillRect(x - w / 2, y - h, w, h * 0.72);
369:         ctx.strokeRect(x - w / 2, y - h, w, h * 0.72);
370:         ctx.strokeStyle = 'rgba(89,122,158,.9)';
371:         ctx.lineWidth = 1.1 * scale;
372:         ctx.beginPath();
373:         ctx.moveTo(x - w / 2 - 2 * scale, y - h);
374:         ctx.lineTo(x - w / 2 - 5 * scale, y - h * 0.35);
375:         ctx.moveTo(x + w / 2 + 2 * scale, y - h);
376:         ctx.lineTo(x + w / 2 + 5 * scale, y - h * 0.35);
377:         ctx.stroke();
378:         ctx.restore();
379:       }
380:     }
381:   }
382: 
383:   drawPlayerTag(ctx, x, y, scale, r) {
384:     const top = y - 132 * scale;
385:     ctx.save();
386:     ctx.globalAlpha = 0.92;
387:     ctx.fillStyle = 'rgba(4,10,20,.72)';
388:     ctx.strokeStyle = 'rgba(247,201,80,.38)';
389:     ctx.lineWidth = 1;
390:     const text = 'YOU';
391:     ctx.font = '700 8px "Barlow Condensed", sans-serif';
392:     const w = ctx.measureText(text).width + 14;
393:     ctx.beginPath();
394:     if (ctx.roundRect) ctx.roundRect(x - w / 2, top - 16, w, 13, 2); else ctx.rect(x - w / 2, top - 16, w, 13);
395:     ctx.fill(); ctx.stroke();
396:     ctx.fillStyle = '#f7c950';
397:     ctx.textAlign = 'center';
398:     ctx.textBaseline = 'middle';
399:     ctx.fillText(text, x, top - 9.5);
400:     ctx.restore();
401:   }
402: 
403:   drawFinishAtmosphere(ctx) {
404:     const x = this.world.sx(this.raceDistance);
405:     if (x < -60 || x > this.W + 60) return;
406:     const grad = ctx.createRadialGradient(x, this.H * 0.77, 0, x, this.H * 0.77, this.H * 0.27);
407:     grad.addColorStop(0, 'rgba(247,201,80,.07)');
408:     grad.addColorStop(1, 'rgba(247,201,80,0)');
409:     ctx.save();
410:     ctx.globalCompositeOperation = 'screen';
411:     ctx.fillStyle = grad;
412:     ctx.beginPath(); ctx.arc(x, this.H * 0.77, this.H * 0.27, 0, Math.PI * 2); ctx.fill();
413:     ctx.restore();
414:   }
415: }
