460:         this.extension = 0.42;
461:         this.game.sound.tone(760, 0.12, 0.05, 'sine', 1040);
462:         this.game.toast('EXTENDED — +0.42 M', 'gold', 1100);
463:         const sx = this.world.sx(this.x);
464:         const sy = this.game.groundY(1, 'longjump') - this.peak * Math.sin(Math.PI * u);
465:         this.game.burst(sx, sy, 10, '#f7c950', 120, 0.5);
466:       } else {
