784:       this.runTime += dt;
785:       this.angleTime += dt;
786:       this.angle = this.optAngle + this.angleAmp * Math.sin(this.angleTime * 3.55 - 0.9);
787:       this.speed = 10.9 * smoothstep(0, 3.5, this.runTime);
788:       this.x += this.speed * dt;
