890:           if (this.goHideTimer <= 0) this.hideCountdown();
891:         }
892:         if (this.miniTimer <= 0) this.renderMiniBoard();
893:         this.applyHud();
894:         break;
895:       case 'results':
896:         if (this.miniTimer <= 0) this.renderMiniBoard();
897:         break;
898:       case 'ceremony':
899:         this.ceremonyT += dt;
900:         this.lastFirework -= dt;
901:         if (this.lastFirework <= 0) {
902:           this.lastFirework = rand(0.8, 1.7);
903:           this.world.addFirework(rand(this.W * 0.15, this.W * 0.85), rand(this.H * 0.12, this.H * 0.4));
904:           this.sound.setCrowd(0.035);
905:         }
906:         break;
907:       default:
908:         break;
909:     }
910:     if (this.state !== 'running' && this.miniTimer <= 0) this.renderMiniBoard();
911:   }
