913:   /* ---------------------------------------------------------------- */
914:   ensureFields() {
915:     if (this.fields) return;
916:     const jitter = {
917:       sprint: [0.055, 2], longjump: [0.09, 2], javelin: [1.1, 1], hurdles: [0.07, 2],
918:       shotput: [0.3, 1], skijump: [1.6, 1], snowboard: [0.06, 2], curling: [9, 0]
919:     };
920:     const f = {};
921:     for (const id of Object.keys(EVENTS)) {
922:       const [j, digits] = jitter[id] || [0.1, 1];
923:       f[id] = {};
924:       for (const a of AI_DATA) {
925:         const base = a[id] ?? 10;
926:         f[id][a.id] = Number((base + rand(-j, j)).toFixed(digits));
927:       }
928:     }
929:     this.fields = f;
930:   }
931:   getField(id) {
932:     this.ensureFields();
933:     return this.fields[id];
934:   }
935:   fieldRank(id, mark) {
936:     if (!mark || mark <= 0) return 8;
937:     const field = this.getField(id);
938:     const lower = EVENTS[id].lower;
939:     let rank = 1;
940:     for (const a of AI_DATA) {
941:       if (lower ? field[a.id] < mark : field[a.id] > mark) rank++;
942:     }
943:     return rank;
944:   }
945:   fieldBoard(id, live) {
946:     const field = this.getField(id);
947:     const meta = EVENTS[id];
948:     const lower = meta.lower;
949:     const rows = this.roster.map(a => ({
950:       id: a.id,
951:       name: a.name,
952:       code: a.code,
953:       player: !!a.player,
954:       value: a.player ? (live || this.bests[id] || 0) : field[a.id]
955:     })).sort((a, b) => lower ? a.value - b.value : b.value - a.value);
956:     return rows.map(r => ({
957:       ...r,
958:       value: r.value ? this.markLabel(id, r.value) : '—'
959:     }));
960:   }
