1187:         size: rand(1.5, 4), color: `rgba(226,246,255,${rand(0.2, 0.4)})`, gravity: 24, drag: 0.4
1188:       });
1189:     }
1190:   }
1191: 
1192:   land() {
1193:     this.state = 'landed';
1194:     this.x = this.landingX;
1195:     this.landTimer = 0;
1196:     this.game.sound.sand(1);
1197:     this.game.sound.cheer(1);
1198:     this.game.shake = Math.max(this.game.shake, 5);
1199:     const sx = this.world.sx(this.landingX);
1200:     const gy = this.game.groundY(1, 'skijump');
