417: /* ================================================================== */
418: /*  LONG JUMP                                                          */
419: /* ================================================================== */
420: export class LongJumpEvent extends BaseEvent {
421:   constructor(game, options = {}) {
422:     super(game, 'longjump', options);
423:     this.meter = clamp(this.W / 24, 16, 52);
424:     this.anchor = 0.37;
425:     this.camX = -(this.W * 0.37) / this.meter;
426:     this.x = 0;
427:     this.runTime = 0;
428:     this.speed = 0;
429:     this.phase = rand(0, 6);
430:     this.state = 'ready';
431:     this.quality = 0;
432:     this.baseDistance = 0;
433:     this.extension = 0;
434:     this.extended = false;
435:     this.flightT = 0;
436:     this.flightDur = 1;
437:     this.takeoffX = 0;
438:     this.landingX = 0;
439:     this.result = 0;
440:     this.peak = 0;
441:     this.landTimer = 0;
442:     this.jumbo = { top: 'OLYMPIA', big: 'JUMP', sub: 'FINAL', value: '0.00' };
443:     this.lastPhase = 0;
444:     this.liveRank = 8;
445:   }
446: 
447:   start() {
448:     this.state = 'run';
449:     this.runTime = 0;
450:     this.game.sound.setCrowd(0.024);
451:   }
452: 
453:   tap() {
454:     if (this.state === 'run') {
455:       this.jump();
456:     } else if (this.state === 'flight' && !this.extended) {
457:       const u = this.flightT / this.flightDur;
458:       if (u > 0.35 && u < 0.7) {
459:         this.extended = true;
460:         this.extension = 0.42;
461:         this.game.sound.tone(760, 0.12, 0.05, 'sine', 1040);
462:         this.game.toast('EXTENDED — +0.42 M', 'gold', 1100);
463:         const sx = this.world.sx(this.x);
464:         const sy = this.game.groundY(1, 'longjump') - this.peak * Math.sin(Math.PI * u);
465:         this.game.burst(sx, sy, 10, '#f7c950', 120, 0.5);
466:       } else {
467:         this.extended = true;
468:         this.game.toast(u <= 0.35 ? 'TOO EARLY TO EXTEND' : 'TOO LATE TO EXTEND', 'red', 900);
469:       }
470:     }
471:   }
472: 
473:   jump(auto = false) {
474:     if (this.state !== 'run') return;
475:     const x = this.x;
476:     let q;
477:     if (x >= 38.1 && x <= 39.9) {
478:       q = 1 - Math.abs(x - 39.0) / 1.3 * 0.12;
479:     } else if (x < 38.1) {
480:       q = clamp(0.22 + Math.max(0, x - 31) / 7.1 * 0.55, 0.22, 0.77);
481:     } else if (x <= 40.6) {
482:       q = 0.58;
483:     } else {
484:       q = 0.34;
485:     }
486:     if (auto) q = Math.min(q, 0.32);
487:     this.quality = q;
488:     this.takeoffX = x;
489:     this.baseDistance = 3.65 + this.speed * 0.337 + q * 1.18;
490:     this.result = this.baseDistance;
491:     const visual = Math.max(3.6, this.baseDistance);
492:     this.landingX = 40 + visual + 0.42;
493:     this.peak = this.H * (0.055 + clamp(this.speed / 12, 0, 1) * 0.04);
494:     this.flightDur = clamp(0.62 + this.baseDistance * 0.038, 0.86, 1.1);
495:     this.flightT = 0;
496:     this.state = 'flight';
497:     this.game.sound.jump();
498:     this.game.shake = Math.max(this.game.shake, 2.5);
499:     this.game.toast(x < 38.1 ? 'EARLY TAKEOFF' : x > 40.3 ? 'OVERSTEP' : 'CLEAN TAKEOFF', x < 38.1 || x > 40.3 ? 'red' : 'gold', 700);
500:   }
501: 
502:   update(dt) {
503:     this.phase += dt;
504:     if (this.state === 'ready') return;
505:     if (this.state === 'run') {
506:       this.runTime += dt;
507:       this.speed = 10.7 * smoothstep(0, 3.7, this.runTime);
508:       this.x += this.speed * dt;
509:       this.phase += this.speed * 0.96 * dt;
510:       if (this.x > 40.9) this.jump(true);
511:       this.updateCamera(dt, this.x, 3.2);
512:       this.spawnDust();
513:     } else if (this.state === 'flight') {
514:       this.flightT += dt;
515:       const u = clamp(this.flightT / this.flightDur, 0, 1);
516:       this.x = lerp(this.takeoffX, this.landingX, u);
517:       this.phase += 2.4 * dt;
518:       this.updateCamera(dt, this.x, 2.5);
519:       if (u >= 1) this.land();
520:     } else if (this.state === 'landed') {
521:       this.landTimer += dt;
522:       this.updateCamera(dt, this.landingX, 1.8);
523:       if (this.landTimer > 1.55) {
524:         this.state = 'done';
525:         this.done(this.result, { quality: this.quality, extended: this.extended });
526:       }
527:     }
528: 
529:     this.liveRank = 1 + this.game.fieldRank('longjump', this.state === 'landed' ? this.result : this.baseDistance);
530:     this.jumbo.value = this.state === 'landed' ? `${this.result.toFixed(2)}` : this.state === 'flight' ? 'AIR' : '0.00';
531:     this.hudState();
532:   }
533: 
534:   hudState() {
535:     const toBoard = Math.max(0, 40 - this.x);
536:     const clockValue = this.state === 'landed'
537:       ? fmtDist(this.result)
538:       : toBoard > 0 ? toBoard.toFixed(1) : 'BOARD';
539:     const clockUnit = this.state === 'landed' ? 'm' : toBoard > 0 ? 'm' : '';
540:     let prompt;
541:     const tap = this.game.touch ? 'TAP' : '↑';
542:     if (this.state === 'run') {
543:       if (this.x < 30) prompt = { key: tap, title: 'BUILD SPEED', sub: 'Stay relaxed — the board is coming', pulse: false };
544:       else if (this.x < 37.6) prompt = { key: tap, title: 'FIND THE BOARD', sub: 'Tap as you enter the glowing zone', pulse: false };
545:       else prompt = { key: tap, title: 'TAKE OFF NOW', sub: 'Hit the board cleanly', pulse: true };
546:     } else if (this.state === 'flight') {
547:       prompt = this.extended
548:         ? { key: '✓', title: 'EXTENSION LOCKED', sub: 'Ride the arc into the sand', pulse: false }
549:         : { key: tap, title: 'TAP TO EXTEND', sub: 'Strike at the top of the flight', pulse: true };
550:     } else if (this.state === 'landed') {
551:       prompt = { key: '✓', title: 'MARK SET', sub: `${this.result.toFixed(2)} metres`, pulse: false };
552:     } else {
553:       prompt = { visible: false };
554:     }
555:     this.hud({
556:       clock: clockValue,
557:       clockUnit,
558:       clockLabel: this.state === 'landed' ? 'MEASURED' : 'TO BOARD',
559:       place: `${this.game.fieldRank('longjump', this.state === 'landed' ? this.result : this.baseDistance)}`,
560:       meter: this.speed,
561:       meterMax: 11.5,
562:       meterUnit: 'M/S',
563:       meterLabel: 'RUNWAY SPEED',
564:       prompt: { visible: true, ...prompt },
565:       action: true,
566:       actionLabel: this.state === 'flight' ? (this.extended ? 'LOCKED' : 'EXTEND') : 'JUMP',
567:       actionSub: this.game.touch ? 'TAP HERE' : (this.state === 'flight' ? 'SPACE / TAP' : 'TAKE OFF'),
568:       actionHot: this.state === 'run' ? (this.x > 37.5 && this.x < 40.1) : (this.state === 'flight' && !this.extended && this.flightT / this.flightDur > 0.3 && this.flightT / this.flightDur < 0.72),
569:       actionDisabled: this.state === 'landed' || (this.state === 'flight' && this.extended)
570:     });
571:     this.game.setMiniBoard(
572:       this.game.fieldBoard('longjump', this.state === 'landed' ? this.result : null),
573:       'FIELD ORDER'
574:     );
575:   }
576: 
577:   spawnDust() {
578:     if (this.speed < 3) return;
579:     const crossed = Math.floor(this.phase / Math.PI);
580:     if (crossed !== this.lastPhase) {
581:       this.lastPhase = crossed;
582:       const x = this.world.sx(this.x) - 10;
583:       const y = this.game.groundY(1, 'longjump');
584:       this.game.spawnParticle({
585:         x, y: y - 2, vx: rand(-45, -10), vy: rand(-25, -5), life: rand(0.3, 0.6),
586:         size: rand(1.2, 3.5), color: 'rgba(255,216,160,.26)', gravity: 30
587:       });
588:     }
589:   }
590: 
591:   land() {
592:     this.state = 'landed';
593:     this.result = this.baseDistance + this.extension;
594:     this.x = this.landingX;
595:     this.landTimer = 0;
596:     this.game.sound.sand(1);
597:     this.game.sound.cheer(0.8);
598:     this.game.shake = Math.max(this.game.shake, 4);
599:     const sx = this.world.sx(this.landingX);
600:     const gy = this.game.groundY(1, 'longjump');
601:     this.game.burst(sx, gy - 5, 26, '#cba465', 170, 0.8);
602:     this.game.burst(sx, gy - 5, 12, '#f7dfaa', 120, 0.55);
603:   }
604: 
605:   render(ctx) {
606:     this.paint();
607:     const ground = this.game.groundY(1, 'longjump');
608:     const scale = this.world.laneScale(1, 'longjump');
609:     const sx = this.world.sx(this.x);
610:     let y = ground;
611:     let pose = 'run';
612:     let height = 0;
613:     let alpha = 1;
614:     if (this.state === 'ready') { pose = 'idle'; }
615:     if (this.state === 'flight') {
616:       const u = clamp(this.flightT / this.flightDur, 0, 1);
617:       height = this.peak * Math.sin(Math.PI * u);
618:       y = ground - height;
619:       pose = 'jump';
620:     } else if (this.state === 'landed') {
621:       pose = 'land';
622:     }
623: 
624:     // shadow shrinks in the air
625:     if (height > 0) {
626:       ctx.save();
627:       ctx.globalAlpha = clamp(1 - height / (this.H * 0.25), 0.15, 0.6);
628:     }
629:     drawAthlete(ctx, {
630:       x: sx, y: y, scale, phase: this.phase, pose,
631:       speed: clamp(this.speed / 11, 0, 1), kit: this.game.playerKit,
632:       glow: 0.16, shadow: height > 0 ? 0.5 : 1
633:     });
634:     if (height > 0) ctx.restore();
635: 
636:     if (this.state === 'flight') {
637:       this.drawTrajectory(ctx, ground, scale);
638:     }
639:     if (this.state === 'landed') {
640:       this.drawMeasurement(ctx, ground, scale);
641:     }
642:     this.drawAthleteAura(ctx, sx, y, scale);
643:   }
644: 
645:   drawAthleteAura(ctx, x, y, scale) {
646:     const g = ctx.createRadialGradient(x, y - 60 * scale, 0, x, y - 60 * scale, 95 * scale);
647:     g.addColorStop(0, 'rgba(255,213,130,.045)');
648:     g.addColorStop(1, 'rgba(255,213,130,0)');
649:     ctx.save();
650:     ctx.globalCompositeOperation = 'screen';
651:     ctx.fillStyle = g;
652:     ctx.fillRect(x - 120 * scale, y - 190 * scale, 240 * scale, 200 * scale);
653:     ctx.restore();
654:   }
655: 
656:   drawTrajectory(ctx, ground, scale) {
657:     const start = this.world.sx(this.takeoffX);
658:     const end = this.world.sx(this.landingX);
659:     ctx.save();
660:     ctx.globalAlpha = 0.33;
661:     ctx.strokeStyle = 'rgba(247,201,80,.7)';
662:     ctx.lineWidth = 1;
663:     ctx.setLineDash([4, 7]);
664:     ctx.beginPath();
665:     for (let i = 0; i <= 20; i++) {
666:       const u = i / 20;
667:       const x = lerp(start, end, u);
668:       const y = ground - this.peak * Math.sin(Math.PI * u) - 50 * scale;
669:       i === 0 ? ctx.moveTo(x, y) : ctx.lineTo(x, y);
670:     }
671:     ctx.stroke();
672:     ctx.restore();
673:   }
674: 
675:   drawMeasurement(ctx, ground, scale) {
676:     const boardX = this.world.sx(40);
677:     const landX = this.world.sx(40 + this.result);
678:     const y = ground + 12;
679:     ctx.save();
680:     ctx.strokeStyle = 'rgba(247,201,80,.85)';
681:     ctx.lineWidth = 1.4;
682:     ctx.beginPath(); ctx.moveTo(boardX, y); ctx.lineTo(landX, y); ctx.stroke();
683:     ctx.fillStyle = 'rgba(247,201,80,.8)';
684:     for (let x = boardX; x <= landX; x += 12) ctx.fillRect(x, y - 3, 1, 6);
685:     ctx.fillStyle = 'rgba(5,11,22,.86)';
686:     ctx.strokeStyle = 'rgba(247,201,80,.55)';
687:     ctx.beginPath();
688:     if (ctx.roundRect) ctx.roundRect(landX - 25, y - 25, 50, 17, 2); else ctx.rect(landX - 25, y - 25, 50, 17);
689:     ctx.fill(); ctx.stroke();
690:     ctx.fillStyle = '#f7c950';
691:     ctx.font = '700 10px "Barlow Condensed", sans-serif';
692:     ctx.textAlign = 'center';
693:     ctx.textBaseline = 'middle';
694:     ctx.fillText(`${this.result.toFixed(2)}m`, landX, y - 16.5);
695:     ctx.restore();
696:   }
697: }
