413:   onAction(action, eventId) {
414:     switch (action) {
415:       case 'start-series':
416:         this.sound.ui();
417:         this.startSeries();
418:         break;
419:       case 'toggle-season':
420:         this.toggleSeason();
421:         break;
422:       case 'practice':
423:         this.sound.ui();
424:         this.openPractice();
425:         break;
426:       case 'close-practice':
427:         this.sound.uiBack();
428:         document.getElementById('practiceMenu').classList.remove('is-active');
429:         break;
430:       case 'practice-event':
431:         this.sound.ui();
432:         this.startPractice(eventId);
433:         break;
434:       case 'enter-event':
435:         this.sound.ui();
436:         this.enterEvent();
437:         break;
438:       case 'pause':
439:         this.openPause();
440:         break;
441:       case 'resume':
442:         this.resume();
443:         break;
444:       case 'restart-event':
445:         this.restartEvent();
446:         break;
447:       case 'quit-event':
448:         this.quitEvent();
449:         break;
450:       case 'guide':
451:         this.openGuide();
452:         break;
453:       case 'close-guide':
454:         this.closeGuide();
455:         break;
456:       case 'sound':
457:         this.toggleSound();
458:         break;
459:       case 'results-next':
460:         this.onResultsNext();
461:         break;
462:       case 'results-replay':
463:         this.onResultsReplay();
464:         break;
465:       case 'to-menu':
466:         this.showMenu();
467:         break;
468:       case 'restart-series':
469:         this.sound.ui();
470:         this.startSeries();
471:         break;
472:       case 'programme':
473:         this.sound.ui();
474:         this.startPractice(eventId);
475:         break;
476:       default:
477:         break;
