641:         c.step = 1;
642:         this.setCountdown('SET', 'STEADY · DO NOT JUMP THE GUN', 'set');
643:         this.sound.countBeep(true);
644:       } else if (c.step === 1 && c.t > 1.95) {
645:         c.step = 2;
646:         this.fireGun();
647:       }
648:     } else {
649:       if (c.step === 0 && c.t > 0.88) {
650:         c.step = 1;
651:         this.setCountdown('SET', 'EYES ON THE LINE', 'set');
652:         this.sound.countBeep(true);
653:       } else if (c.step === 1 && c.t > 1.58) {
654:         c.step = 2;
655:         this.fireGo();
656:       }
657:     }
658:   }
