739:   paintWorld(mode, opts = {}) {
740:     const ctx = this.ctx;
741:     const w = this.world;
742:     w.season = this.season;
743:     const viewMode = this.currentEvent?.worldMode || mode;
744:     w.mode = viewMode;
745:     if (mode === 'ceremony') {
746:       // Camera is owned by renderCeremony; do not overwrite it with the event.
747:     } else if (this.currentEvent) {
748:       w.setCamera(this.currentEvent.camX, this.currentEvent.meter, this.currentEvent.anchor, viewMode);
749:     } else if (mode === 'menu') {
750:       w.setCamera(8 + Math.sin(this.menuT * 0.07) * 1.4, clamp(this.W / 24, 16, 54), 0.42, mode);
751:     } else {
752:       w.setCamera(12, clamp(this.W / 24, 16, 54), 0.42, viewMode);
753:     }
754:     w.playerLane = this.currentEvent?.playerLane ?? 3;
755:     w.drawSky(ctx, { mode });
756:     w.drawCity(ctx);
757:     w.drawRoof(ctx);
758:     w.drawCrowd(ctx);
759:     w.drawJumbotron(ctx, { ...(opts.jumbo || {}), mode });
760:     w.drawLedRibbon(ctx, { ribbon: opts.ribbon });
761:     w.drawGround(ctx, { mode });
762:     w.drawFloodlights(ctx);
763:     w.drawAtmosphere(ctx);
764:   }
