766:   render() {
767:     const ctx = this.ctx;
768:     ctx.setTransform(this.dpr, 0, 0, this.dpr, 0, 0);
769:     ctx.clearRect(0, 0, this.W, this.H);
770:     const shake = this.shake;
771:     ctx.save();
772:     if (shake > 0.15) {
773:       ctx.translate(rand(-shake, shake) * 0.55, rand(-shake, shake) * 0.4);
774:     }
775: 
776:     if (this.state === 'menu' || (this.state === 'guide')) {
777:       this.renderMenu();
778:     } else if (this.state === 'intro') {
779:       if (this.currentEvent) this.currentEvent.render(ctx);
780:     } else if (this.state === 'countdown' || this.state === 'false-start' || this.state === 'running' || this.state === 'results' || this.paused) {
781:       if (this.currentEvent) this.currentEvent.render(ctx);
782:     } else if (this.state === 'ceremony') {
783:       this.renderCeremony();
784:     } else {
785:       this.renderMenu();
786:     }
787:     ctx.restore();
788: 
789:     this.particles.draw(ctx);
790: 
791:     if (this.state === 'ceremony') {
792:       this.world.drawFireworks(ctx);
793:     }
794:     if (!this.wasAnimating) this.wasAnimating = true;
795:   }
