838:   renderCeremony() {
839:     const ctx = this.ctx;
840:     this.world.setCamera(16 + Math.sin(this.ceremonyT * 0.06) * 1.2, clamp(this.W / 24, 16, 54), 0.42, 'ceremony');
841:     this.paintWorld('ceremony', {
842:       jumbo: { top: 'OLYMPIA', big: 'PODIUM', sub: this.series?.season === 'winter' ? 'THE WINTER SESSION' : 'THE NIGHT SESSION', value: `${this.standings?.[0]?.total ?? 0} PTS` }
843:     });
844:     this.world.drawCeremonyPodium(ctx, this.standings || [], 'player', this.ceremonyT);
845:     this.world.drawFireworks(ctx);
846:     // extra stage glow
847:     ctx.save();
848:     ctx.globalCompositeOperation = 'screen';
849:     const g = ctx.createRadialGradient(this.W * 0.46, this.H * 0.7, 0, this.W * 0.46, this.H * 0.7, this.W * 0.3);
850:     g.addColorStop(0, 'rgba(255,215,125,.10)');
851:     g.addColorStop(1, 'rgba(255,200,100,0)');
852:     ctx.fillStyle = g;
853:     ctx.fillRect(0, 0, this.W, this.H);
854:     ctx.restore();
855:   }
