1023: /* ================================================================== */
1024: /*  SKI JUMP                                                           */
1025: /* ================================================================== */
1026: export class SkiJumpEvent extends BaseEvent {
1027:   constructor(game, options = {}) {
1028:     super(game, 'skijump', options);
1029:     this.worldMode = 'skijump';
1030:     this.meter = clamp(this.W / 25, 16, 50);
1031:     this.anchor = 0.36;
1032:     this.camX = -(this.W * 0.36) / this.meter;
1033:     this.x = 0;
1034:     this.runTime = 0;
1035:     this.speed = 0;
1036:     this.phase = rand(0, 6);
1037:     this.state = 'ready';
1038:     this.quality = 0;
1039:     this.result = 0;
1040:     this.extension = 0;
1041:     this.extended = false;
1042:     this.flightT = 0;
1043:     this.flightDur = 3.4;
1044:     this.takeoffX = 0;
1045:     this.landingX = 0;
1046:     this.peak = 0;
1047:     this.landTimer = 0;
1048:     this.jumbo = { top: 'OLYMPIA', big: 'SKI JUMP', sub: 'WINTER FINAL', value: '0.0' };
1049:     this.liveRank = 8;
1050:   }
1051: 
1052:   start() {
1053:     this.state = 'run';
1054:     this.runTime = 0;
1055:     this.game.sound.setCrowd(0.024);
1056:   }
1057: 
1058:   tap() {
1059:     if (this.state === 'run') {
1060:       this.jump();
1061:     } else if (this.state === 'flight' && !this.extended) {
1062:       const u = this.flightT / this.flightDur;
1063:       if (u > 0.32 && u < 0.72) {
1064:         this.extended = true;
1065:         this.extension = 2.4 + (1 - Math.abs(u - 0.5) * 2) * 2.2;
1066:         this.result += this.extension;
1067:         this.game.sound.tone(820, 0.14, 0.06, 'sine', 1180);
1068:         this.game.toast(`EXTENDED — +${this.extension.toFixed(1)} M`, 'gold', 1000);
1069:         this.game.burst(this.world.sx(this.x), this.game.groundY(1, 'skijump') - this.height(), 12, '#dfefff', 90, 0.6);
1070:       } else {
1071:         this.extended = true;
1072:         this.game.toast(u <= 0.32 ? 'TOO EARLY' : 'TOO LATE', 'red', 800);
1073:       }
1074:     }
1075:   }
1076: 
1077:   height() {
1078:     if (this.state !== 'flight') return 0;
1079:     return this.peak * Math.sin(Math.PI * clamp(this.flightT / this.flightDur, 0, 1));
1080:   }
1081: 
1082:   jump(auto = false) {
1083:     if (this.state !== 'run') return;
1084:     const x = this.x;
1085:     let q;
1086:     if (x >= 37.4 && x <= 40.8) q = 1 - Math.abs(x - 39.1) / 3.4 * 0.28;
1087:     else if (x < 37.4) q = clamp(0.24 + Math.max(0, x - 30) / 7.4 * 0.6, 0.24, 0.82);
1088:     else q = 0.4;
1089:     if (auto) q = Math.min(q, 0.34);
1090:     const sf = clamp(this.speed / 13.2, 0, 1);
1091:     this.quality = q;
1092:     this.takeoffX = 40.5;
1093:     this.result = 87 + q * 35 + sf * 9 + rand(-0.8, 0.8);
1094:     if (auto) this.result *= 0.9;
1095:     this.result = clamp(this.result, 78, 143);
1096:     this.landingX = this.takeoffX + this.result;
1097:     this.peak = this.H * (0.16 + sf * 0.08);
1098:     this.flightDur = 2.9 + this.result * 0.012;
1099:     this.flightT = 0;
1100:     this.state = 'flight';
1101:     this.game.sound.whoosh(1);
1102:     this.game.sound.cheer(0.7);
1103:     this.game.shake = Math.max(this.game.shake, 4);
1104:     this.game.toast(x < 37.4 ? 'EARLY LIP' : x > 40.8 ? 'LATE LIP' : 'CLEAN LAUNCH', x < 37.4 || x > 40.8 ? 'red' : 'gold', 760);
1105:   }
1106: 
1107:   update(dt) {
1108:     this.phase += dt;
1109:     if (this.state === 'ready') return;
1110:     if (this.state === 'run') {
1111:       this.runTime += dt;
1112:       this.speed = 13.2 * smoothstep(0, 3.4, this.runTime);
1113:       this.x += this.speed * dt;
1114:       this.phase += this.speed * 0.8 * dt;
1115:       if (this.x > 41.4) this.jump(true);
1116:       this.updateCamera(dt, this.x, 3.4);
1117:       this.spawnSpray();
1118:     } else if (this.state === 'flight') {
1119:       this.flightT += dt;
1120:       const u = clamp(this.flightT / this.flightDur, 0, 1);
1121:       this.x = lerp(this.takeoffX, this.landingX, u);
1122:       const targetMeter = clamp(this.W / 155, 3.4, 10);
1123:       this.meter = lerp(this.meter, targetMeter, 1 - Math.exp(-1.5 * dt));
1124:       const targetCam = (this.takeoffX + this.landingX) / 2 - (this.W * 0.5) / this.meter;
1125:       this.camX = lerp(this.camX, targetCam, 1 - Math.exp(-1.9 * dt));
1126:       this.anchor = lerp(this.anchor, 0.5, 1 - Math.exp(-1.6 * dt));
1127:       this.world.setCamera(this.camX, this.meter, this.anchor, 'skijump');
1128:       if (u >= 1) this.land();
1129:     } else if (this.state === 'landed') {
1130:       this.landTimer += dt;
1131:       this.updateCamera(dt, this.landingX, 2);
1132:       if (this.landTimer > 2.1) {
1133:         this.state = 'done';
1134:         this.done(this.result, { quality: this.quality, extended: this.extended });
1135:         return;
1136:       }
1137:     }
1138:     this.liveRank = 1 + this.game.fieldRank('skijump', this.state === 'landed' ? this.result : 0);
1139:     this.jumbo.value = this.state === 'landed' ? this.result.toFixed(1) : this.state === 'flight' ? 'AIR' : '0.0';
1140:     this.hudState();
1141:   }
1142: 
1143:   hudState() {
1144:     const toLip = Math.max(0, 40.5 - this.x);
1145:     const flying = this.state === 'flight';
1146:     const clock = this.state === 'landed' ? fmtDist(this.result, 1) : flying ? fmtDist(this.result, 1) : toLip.toFixed(1);
1147:     const label = this.state === 'landed' ? 'MEASURED' : flying ? 'PROJECTED' : 'TO THE LIP';
1148:     const tap = this.game.touch ? 'TAP' : '↑';
1149:     let prompt;
1150:     if (this.state === 'run') {
1151:       prompt = {
1152:         key: tap, title: this.x > 34 ? 'LAUNCH AT THE LIP' : 'BUILD THE IN-RUN',
1153:         sub: this.x > 34 ? 'Tap as you reach the edge' : `${toLip.toFixed(1)}m to the lip — stay tucked`,
1154:         pulse: this.x > 36.6
1155:       };
1156:     } else if (flying) {
1157:       prompt = this.extended
1158:         ? { key: '✓', title: 'PERFECT EXTENSION', sub: 'Hold the line all the way down', pulse: false }
1159:         : { key: tap, title: 'TAP AT THE APEX', sub: 'Stretch the jump for extra metres', pulse: true };
1160:     } else if (this.state === 'landed') {
1161:       prompt = { key: '✓', title: 'JUMP MEASURED', sub: `${this.result.toFixed(1)} metres`, pulse: false };
1162:     } else {
1163:       prompt = { visible: false };
1164:     }
1165:     this.hud({
1166:       clock, clockUnit: this.state === 'landed' || flying ? 'm' : 'm', clockLabel: label,
1167:       place: `${this.game.fieldRank('skijump', this.state === 'landed' ? this.result : 0)}`,
1168:       meter: this.speed, meterMax: 13.5, meterUnit: 'M/S', meterLabel: 'IN-RUN SPEED',
1169:       prompt: { visible: true, ...prompt },
1170:       action: true,
1171:       actionLabel: flying ? (this.extended ? 'LOCKED' : 'EXTEND') : 'LAUNCH',
1172:       actionSub: this.game.touch ? 'TAP HERE' : 'SPACE / TAP',
1173:       actionHot: this.state === 'run' ? this.x > 36.5 : (flying && !this.extended && this.flightT / this.flightDur > 0.3 && this.flightT / this.flightDur < 0.72),
1174:       actionDisabled: this.state === 'landed' || (flying && this.extended)
1175:     });
1176:     this.game.setMiniBoard(this.game.fieldBoard('skijump', this.state === 'landed' ? this.result : null), 'FIELD ORDER');
1177:   }
1178: 
1179:   spawnSpray() {
1180:     if (this.speed < 4) return;
1181:     const crossed = Math.floor(this.phase / 2.2);
1182:     if (crossed !== this.lastPhase) {
1183:       this.lastPhase = crossed;
1184:       this.game.spawnParticle({
1185:         x: this.world.sx(this.x) - 8, y: this.game.groundY(1, 'skijump') - 2,
1186:         vx: rand(-55, -12), vy: rand(-28, -6), life: rand(0.3, 0.65),
1187:         size: rand(1.5, 4), color: `rgba(226,246,255,${rand(0.2, 0.4)})`, gravity: 24, drag: 0.4
1188:       });
1189:     }
1190:   }
1191: 
1192:   land() {
1193:     this.state = 'landed';
1194:     this.x = this.landingX;
1195:     this.landTimer = 0;
1196:     this.game.sound.sand(1);
1197:     this.game.sound.cheer(1);
1198:     this.game.shake = Math.max(this.game.shake, 5);
1199:     const sx = this.world.sx(this.landingX);
1200:     const gy = this.game.groundY(1, 'skijump');
1201:     this.game.burst(sx, gy - 6, 34, '#e4f3ff', 170, 0.9);
1202:     this.game.burst(sx, gy - 6, 16, '#ffffff', 120, 0.6);
1203:     this.game.toast(`${this.result.toFixed(1)} M`, 'gold', 1400);
1204:   }
1205: 
1206:   render(ctx) {
1207:     this.paint();
1208:     const ground = this.game.groundY(1, 'skijump');
1209:     const zoomScale = clamp(this.meter / clamp(this.W / 25, 16, 50), 0.2, 1);
1210:     const scale = this.world.laneScale(1, 'skijump') * zoomScale;
1211:     const sx = this.world.sx(this.x);
1212:     const height = this.height();
1213:     let pose = this.state === 'ready' ? 'idle' : 'run';
1214:     if (this.state === 'flight') pose = 'jump';
1215:     if (this.state === 'landed') pose = 'land';
1216:     drawAthlete(ctx, {
1217:       x: sx, y: ground - height, scale, phase: this.phase, pose,
1218:       speed: clamp(this.speed / 13, 0, 1), kit: this.game.playerKit,
1219:       glow: 0.18, shadow: height > 0 ? 0.45 : 1, skis: true,
1220:       flip: false
1221:     });
1222:     if (this.state === 'landed') this.drawMeasurement(ctx, ground);
1223:   }
1224: 
1225:   drawMeasurement(ctx, ground) {
1226:     const lineX = this.world.sx(this.takeoffX);
1227:     const landX = this.world.sx(this.landingX);
1228:     const y = ground + 16;
1229:     ctx.save();
1230:     ctx.strokeStyle = 'rgba(143,228,255,.85)';
1231:     ctx.lineWidth = 1.3;
1232:     ctx.beginPath(); ctx.moveTo(lineX, y); ctx.lineTo(landX, y); ctx.stroke();
1233:     ctx.fillStyle = 'rgba(143,228,255,.7)';
1234:     for (let x = lineX; x <= landX; x += 12) ctx.fillRect(x, y - 3, 1, 6);
1235:     ctx.fillStyle = 'rgba(5,11,22,.9)';
1236:     ctx.strokeStyle = 'rgba(143,228,255,.6)';
1237:     ctx.beginPath();
1238:     if (ctx.roundRect) ctx.roundRect(landX - 30, y - 28, 60, 18, 2); else ctx.rect(landX - 30, y - 28, 60, 18);
1239:     ctx.fill(); ctx.stroke();
1240:     ctx.fillStyle = '#bdeaff';
1241:     ctx.font = '700 11px "Barlow Condensed", sans-serif';
1242:     ctx.textAlign = 'center';
1243:     ctx.textBaseline = 'middle';
