1249: /* ================================================================== */
1250: /*  CURLING                                                            */
1251: /* ================================================================== */
1252: export class CurlingEvent extends BaseEvent {
1253:   constructor(game, options = {}) {
1254:     super(game, 'curling', options);
1255:     this.worldMode = 'curling';
1256:     this.meter = clamp(this.W / 36, 14, 34);
1257:     this.anchor = 0.5;
1258:     this.camX = 1.5;
1259:     this.x = 3.2;
1260:     this.state = 'ready';
1261:     this.aimT = 0;
1262:     this.power = 0;
1263:     this.v = 0;
1264:     this.sweeps = 0;
1265:     this.result = 0;
1266:     this.stopTimer = 0;
1267:     this.target = 27.5;
1268:     this.jumbo = { top: 'OLYMPIA', big: 'CURLING', sub: 'WINTER FINAL', value: '—' };
1269:     this.trail = [];
1270:   }
1271: 
1272:   start() {
1273:     this.state = 'aim';
1274:     this.aimT = 0;
1275:     this.game.sound.setCrowd(0.02);
1276:     this.game.toast('JUDGE THE WEIGHT', 'gold', 1000);
1277:   }
1278: 
1279:   tap() {
1280:     if (this.state === 'aim') {
1281:       this.power = clamp(0.5 - 0.5 * Math.cos(this.aimT * 2.3), 0.05, 1);
1282:       this.v = 8.2 + this.power * 4.9;
1283:       this.state = 'slide';
1284:       this.sweeps = 0;
1285:       this.game.sound.whoosh(0.8);
1286:       this.game.shake = Math.max(this.game.shake, 2);
1287:       this.game.toast(`RELEASED — ${Math.round(this.power * 100)}% WEIGHT`, 'gold', 850);
1288:     } else if (this.state === 'slide' && this.sweeps < 5) {
1289:       this.sweeps++;
1290:       this.v += 0.28;
1291:       this.game.sound.step(0.45);
1292:       this.game.burst(this.world.sx(this.x - 0.6), this.game.groundY(1, 'curling') - 3, 3, 'rgba(214,246,255,.55)', 50, 0.35);
1293:     }
1294:   }
1295: 
1296:   update(dt) {
1297:     this.phase += dt;
1298:     if (this.state === 'ready') return;
1299:     if (this.state === 'aim') {
1300:       this.aimT += dt;
1301:       this.power = clamp(0.5 - 0.5 * Math.cos(this.aimT * 2.3), 0.05, 1);
1302:       this.updateCamera(dt, 14, 11);
1303:       this.hudState();
1304:       return;
1305:     }
1306:     if (this.state === 'slide') {
1307:       this.x += this.v * dt;
1308:       this.v = Math.max(0, this.v - 2.35 * dt);
1309:       const targetCam = clamp(this.x - 7, 2, 22);
1310:       this.camX = lerp(this.camX, targetCam, 1 - Math.exp(-1.6 * dt));
1311:       this.world.setCamera(this.camX, this.meter, this.anchor, 'curling');
1312:       if (this.v <= 0.08) {
1313:         this.v = 0;
1314:         this.state = 'stopped';
1315:         this.stopTimer = 0;
1316:         this.result = clamp(Math.abs(this.x - this.target) * 100 + rand(-3, 3), 1, 420);
1317:         this.game.sound.sand(0.6);
1318:         this.game.sound.cheer(this.result < 40 ? 1.1 : 0.45);
1319:         this.game.toast(this.result < 8 ? 'ON THE BUTTON!' : this.result < 40 ? 'IN THE HOUSE' : 'TOO HEAVY / LIGHT', this.result < 40 ? 'gold' : 'red', 1200);
1320:         this.game.burst(this.world.sx(this.x), this.game.groundY(1, 'curling') - 3, 16, '#dff5ff', 90, 0.6);
1321:       }
1322:       this.hudState();
1323:       return;
1324:     }
1325:     if (this.state === 'stopped') {
1326:       this.stopTimer += dt;
1327:       this.hudState();
1328:       if (this.stopTimer > 2.1) {
1329:         this.state = 'done';
1330:         this.done(this.result, { sweeps: this.sweeps });
1331:         return;
1332:       }
1333:     }
1334:   }
1335: 
1336:   hudState() {
1337:     const aiming = this.state === 'aim';
1338:     const sliding = this.state === 'slide';
1339:     const stopped = this.state === 'stopped' || this.state === 'done';
1340:     const remaining = Math.abs(this.target - this.x);
1341:     const clock = stopped ? String(Math.round(this.result)) : sliding ? `${remaining.toFixed(1)}` : `${Math.round(this.power * 100)}`;
1342:     const unit = stopped ? 'cm' : sliding ? 'm' : '%';
1343:     const label = stopped ? 'FROM THE BUTTON' : sliding ? 'TO THE BUTTON' : 'STONE WEIGHT';
1344:     const tap = this.game.touch ? 'TAP' : 'SPACE';
1345:     let prompt;
1346:     if (aiming) prompt = { key: tap, title: 'FIND THE WEIGHT', sub: `${Math.round(this.power * 100)}% — tap to release at the button`, pulse: this.power > 0.62 && this.power < 0.86 };
1347:     else if (sliding) prompt = { key: tap, title: 'SWEEP IT HOME', sub: this.sweeps < 5 ? `Tap to sweep · ${5 - this.sweeps} left` : 'The stone is running', pulse: this.sweeps < 5 };
1348:     else prompt = { key: '✓', title: this.result < 40 ? 'IN THE HOUSE' : 'STONE AT REST', sub: `${Math.round(this.result)} cm from the button`, pulse: false };
1349:     this.hud({
1350:       clock, clockUnit: unit, clockLabel: label,
1351:       place: stopped ? `${this.game.fieldRank('curling', this.result)}` : '—',
1352:       meter: aiming ? this.power * 100 : this.v * 10, meterMax: aiming ? 100 : 140,
1353:       meterUnit: aiming ? '%' : 'KM/H', meterLabel: aiming ? 'STONE WEIGHT' : 'SLIDE SPEED',
1354:       prompt: { visible: true, ...prompt },
1355:       action: true,
1356:       actionLabel: aiming ? 'SLIDE' : sliding ? 'SWEEP' : 'SETTLED',
1357:       actionSub: this.game.touch ? 'TAP HERE' : 'SPACE / TAP',
1358:       actionHot: aiming ? (this.power > 0.62 && this.power < 0.86) : sliding,
1359:       actionDisabled: stopped || (sliding && this.sweeps >= 5)
1360:     });
1361:     this.jumbo.value = stopped ? `${Math.round(this.result)}cm` : sliding ? fmtDist(this.x, 1) : `${Math.round(this.power * 100)}%`;
1362:     this.game.setMiniBoard(this.game.fieldBoard('curling', stopped ? this.result : null), 'HOUSE ORDER');
1363:   }
1364: 
1365:   render(ctx) {
1366:     this.paint();
1367:     const ground = this.game.groundY(1, 'curling');
1368:     const scale = this.world.laneScale(1, 'curling');
1369:     const sxStone = this.world.sx(this.x);
1370:     // athlete at the hack with a broom
1371:     const athleteX = this.world.sx(2.2);
1372:     drawAthlete(ctx, {
1373:       x: athleteX, y: ground, scale: scale * 0.95, phase: this.phase * 0.5,
1374:       pose: 'idle', speed: 0.1, kit: this.game.playerKit, glow: 0.15, shadow: 1
1375:     });
1376:     // released stone
1377:     this.drawStone(ctx, sxStone, ground - 0.08 * this.meter, this.meter);
1378:     // aim guide
1379:     if (this.state === 'aim') {
1380:       ctx.save();
1381:       ctx.strokeStyle = 'rgba(143,228,255,.25)';
1382:       ctx.lineWidth = 1;
1383:       ctx.setLineDash([4, 8]);
1384:       const tx = this.world.sx(this.x + 4 + this.power * 24);
1385:       ctx.beginPath(); ctx.moveTo(sxStone, ground - 2); ctx.lineTo(tx, ground - 2); ctx.stroke();
1386:       ctx.restore();
1387:     }
1388:     if (this.state === 'stopped' || this.state === 'done') this.drawMeasure(ctx, ground);
1389:   }
1390: 
1391:   drawStone(ctx, x, y, meter) {
1392:     const r = clamp(0.42 * meter, 5, 15);
1393:     ctx.save();
1394:     ctx.fillStyle = 'rgba(0,0,0,.28)';
1395:     ctx.beginPath(); ctx.ellipse(x + 2, y + 2, r * 1.05, r * 0.34, 0, 0, Math.PI * 2); ctx.fill();
1396:     const g = ctx.createLinearGradient(x - r, y - r, x + r, y + r);
1397:     g.addColorStop(0, '#8d96a5');
1398:     g.addColorStop(0.45, '#4c5666');
1399:     g.addColorStop(1, '#252d3a');
1400:     ctx.fillStyle = g;
1401:     ctx.beginPath(); ctx.ellipse(x, y, r * 0.9, r * 0.58, 0, 0, Math.PI * 2); ctx.fill();
1402:     ctx.strokeStyle = 'rgba(230,244,255,.42)';
1403:     ctx.lineWidth = 1;
1404:     ctx.stroke();
1405:     ctx.fillStyle = '#b93b34';
1406:     ctx.beginPath(); ctx.ellipse(x, y - r * 0.08, r * 0.32, r * 0.2, 0, 0, Math.PI * 2); ctx.fill();
1407:     ctx.strokeStyle = 'rgba(255,255,255,.5)';
1408:     ctx.lineWidth = Math.max(1, r * 0.1);
1409:     ctx.beginPath(); ctx.moveTo(x - r * 0.28, y - r * 0.5); ctx.lineTo(x + r * 0.3, y - r * 0.9); ctx.stroke();
