185:       } else {
186:         ctx.beginPath();
187:         ctx.arc(0, 0, Math.max(0.3, p.size * (0.4 + a * 0.6)), 0, TAU);
188:         ctx.fill();
189:       }
190:       ctx.restore();
191:     }
192:   }
