1239:     ctx.fill(); ctx.stroke();
1240:     ctx.fillStyle = '#bdeaff';
1241:     ctx.font = '700 11px "Barlow Condensed", sans-serif';
1242:     ctx.textAlign = 'center';
1243:     ctx.textBaseline = 'middle';
1244:     ctx.fillText(`${this.result.toFixed(1)}m`, landX, y - 19);
