559:       place: `${this.game.fieldRank('longjump', this.state === 'landed' ? this.result : this.baseDistance)}`,
560:       meter: this.speed,
561:       meterMax: 11.5,
562:       meterUnit: 'M/S',
563:       meterLabel: 'RUNWAY SPEED',
564:       prompt: { visible: true, ...prompt },
565:       action: true,
566:       actionLabel: this.state === 'flight' ? (this.extended ? 'LOCKED' : 'EXTEND') : 'JUMP',
567:       actionSub: this.game.touch ? 'TAP HERE' : (this.state === 'flight' ? 'SPACE / TAP' : 'TAKE OFF'),
568:       actionHot: this.state === 'run' ? (this.x > 37.5 && this.x < 40.1) : (this.state === 'flight' && !this.extended && this.flightT / this.flightDur > 0.3 && this.flightT / this.flightDur < 0.72),
569:       actionDisabled: this.state === 'landed' || (this.state === 'flight' && this.extended)
570:     });
571:     this.game.setMiniBoard(
572:       this.game.fieldBoard('longjump', this.state === 'landed' ? this.result : null),
573:       'FIELD ORDER'
574:     );
575:   }
576: 
577:   spawnDust() {
578:     if (this.speed < 3) return;
579:     const crossed = Math.floor(this.phase / Math.PI);
580:     if (crossed !== this.lastPhase) {
581:       this.lastPhase = crossed;
582:       const x = this.world.sx(this.x) - 10;
583:       const y = this.game.groundY(1, 'longjump');
584:       this.game.spawnParticle({
585:         x, y: y - 2, vx: rand(-45, -10), vy: rand(-25, -5), life: rand(0.3, 0.6),
586:         size: rand(1.2, 3.5), color: 'rgba(255,216,160,.26)', gravity: 30
587:       });
588:     }
589:   }
590: 
591:   land() {
592:     this.state = 'landed';
593:     this.result = this.baseDistance + this.extension;
594:     this.x = this.landingX;
595:     this.landTimer = 0;
596:     this.game.sound.sand(1);
597:     this.game.sound.cheer(0.8);
598:     this.game.shake = Math.max(this.game.shake, 4);
599:     const sx = this.world.sx(this.landingX);
600:     const gy = this.game.groundY(1, 'longjump');
601:     this.game.burst(sx, gy - 5, 26, '#cba465', 170, 0.8);
602:     this.game.burst(sx, gy - 5, 12, '#f7dfaa', 120, 0.55);
603:   }
604: 
605:   render(ctx) {
606:     this.paint();
607:     const ground = this.game.groundY(1, 'longjump');
608:     const scale = this.world.laneScale(1, 'longjump');
609:     const sx = this.world.sx(this.x);
610:     let y = ground;
611:     let pose = 'run';
612:     let height = 0;
613:     let alpha = 1;
614:     if (this.state === 'ready') { pose = 'idle'; }
615:     if (this.state === 'flight') {
616:       const u = clamp(this.flightT / this.flightDur, 0, 1);
617:       height = this.peak * Math.sin(Math.PI * u);
618:       y = ground - height;
619:       pose = 'jump';
620:     } else if (this.state === 'landed') {
621:       pose = 'land';
622:     }
623: 
624:     // shadow shrinks in the air
625:     if (height > 0) {
626:       ctx.save();
627:       ctx.globalAlpha = clamp(1 - height / (this.H * 0.25), 0.15, 0.6);
628:     }
629:     drawAthlete(ctx, {
630:       x: sx, y: y, scale, phase: this.phase, pose,
631:       speed: clamp(this.speed / 11, 0, 1), kit: this.game.playerKit,
632:       glow: 0.16, shadow: height > 0 ? 0.5 : 1
633:     });
634:     if (height > 0) ctx.restore();
635: 
636:     if (this.state === 'flight') {
637:       this.drawTrajectory(ctx, ground, scale);
638:     }
639:     if (this.state === 'landed') {
640:       this.drawMeasurement(ctx, ground, scale);
641:     }
642:     this.drawAthleteAura(ctx, sx, y, scale);
643:   }
644: 
645:   drawAthleteAura(ctx, x, y, scale) {
646:     const g = ctx.createRadialGradient(x, y - 60 * scale, 0, x, y - 60 * scale, 95 * scale);
647:     g.addColorStop(0, 'rgba(255,213,130,.045)');
648:     g.addColorStop(1, 'rgba(255,213,130,0)');
649:     ctx.save();
650:     ctx.globalCompositeOperation = 'screen';
651:     ctx.fillStyle = g;
652:     ctx.fillRect(x - 120 * scale, y - 190 * scale, 240 * scale, 200 * scale);
653:     ctx.restore();
654:   }
655: 
656:   drawTrajectory(ctx, ground, scale) {
657:     const start = this.world.sx(this.takeoffX);
658:     const end = this.world.sx(this.landingX);
659:     ctx.save();
660:     ctx.globalAlpha = 0.33;
661:     ctx.strokeStyle = 'rgba(247,201,80,.7)';
662:     ctx.lineWidth = 1;
663:     ctx.setLineDash([4, 7]);
664:     ctx.beginPath();
665:     for (let i = 0; i <= 20; i++) {
666:       const u = i / 20;
667:       const x = lerp(start, end, u);
668:       const y = ground - this.peak * Math.sin(Math.PI * u) - 50 * scale;
669:       i === 0 ? ctx.moveTo(x, y) : ctx.lineTo(x, y);
670:     }
671:     ctx.stroke();
672:     ctx.restore();
673:   }
674: 
675:   drawMeasurement(ctx, ground, scale) {
676:     const boardX = this.world.sx(40);
677:     const landX = this.world.sx(40 + this.result);
678:     const y = ground + 12;
679:     ctx.save();
680:     ctx.strokeStyle = 'rgba(247,201,80,.85)';
681:     ctx.lineWidth = 1.4;
682:     ctx.beginPath(); ctx.moveTo(boardX, y); ctx.lineTo(landX, y); ctx.stroke();
683:     ctx.fillStyle = 'rgba(247,201,80,.8)';
684:     for (let x = boardX; x <= landX; x += 12) ctx.fillRect(x, y - 3, 1, 6);
685:     ctx.fillStyle = 'rgba(5,11,22,.86)';
686:     ctx.strokeStyle = 'rgba(247,201,80,.55)';
687:     ctx.beginPath();
688:     if (ctx.roundRect) ctx.roundRect(landX - 25, y - 25, 50, 17, 2); else ctx.rect(landX - 25, y - 25, 50, 17);
689:     ctx.fill(); ctx.stroke();
690:     ctx.fillStyle = '#f7c950';
691:     ctx.font = '700 10px "Barlow Condensed", sans-serif';
692:     ctx.textAlign = 'center';
693:     ctx.textBaseline = 'middle';
694:     ctx.fillText(`${this.result.toFixed(2)}m`, landX, y - 16.5);
695:     ctx.restore();
696:   }
697: }
