699: /* ================================================================== */
700: /*  JAVELIN                                                            */
701: /* ================================================================== */
702: export class JavelinEvent extends BaseEvent {
703:   constructor(game, options = {}) {
704:     const id = options.id || 'javelin';
705:     super(game, id, options);
706:     this.worldMode = 'javelin';
707:     this.optAngle = options.optAngle ?? 36;
708:     this.angleAmp = options.angleAmp ?? 16;
709:     this.baseResult = options.base ?? 62;
710:     this.spanResult = options.span ?? 31;
711:     this.maxResult = options.max ?? 93.4;
712:     this.isShot = id === 'shotput';
713:     this.meter = clamp(this.W / 24, 16, 52);
714:     this.anchor = 0.37;
715:     this.camX = -(this.W * 0.37) / this.meter;
716:     this.x = 0;
717:     this.throwerX = 0;
718:     this.runTime = 0;
719:     this.speed = 0;
720:     this.phase = rand(0, 6);
721:     this.angle = this.optAngle;
722:     this.angleTime = 0;
723:     this.state = 'ready';
724:     this.result = 0;
725:     this.flightT = 0;
726:     this.flightDur = 3.6;
727:     this.startX = 0;
728:     this.landX = 36;
729:     this.peak = 0;
730:     this.landTimer = 0;
731:     this.releaseScore = 1;
732:     this.angleScore = 1;
733:     this.jumbo = { top: 'OLYMPIA', big: this.isShot ? 'SHOT PUT' : 'JAVELIN', sub: 'FINAL', value: '0.00' };
734:     this.lastPhase = 0;
735:     this.trail = [];
736:     this.liveRank = 8;
737:   }
738: 
739:   start() {
740:     this.state = 'run';
741:     this.runTime = 0;
742:     this.game.sound.setCrowd(0.023);
743:   }
744: 
745:   tap() {
746:     if (this.state === 'run') this.throwSpear();
747:   }
748: 
749:   throwSpear(auto = false) {
750:     if (this.state !== 'run') return;
751:     const x = this.x;
752:     this.releaseScore = 1 - clamp((36 - x) / 13, 0, 1) * 0.6;
753:     this.angleScore = 1 - clamp(Math.abs(this.angle - this.optAngle) / 28, 0, 1) * 0.7;
754:     const precision = Math.max(0, 1 - Math.abs(this.angle - this.optAngle) / 4) * (this.isShot ? 0.35 : 0.8)
755:       + Math.max(0, 1 - Math.abs(36 - x) / 1.6) * (this.isShot ? 0.25 : 0.5);
756:     const speedFactor = clamp(this.speed / 10.9, 0, 1);
757:     if (auto) this.angleScore = 0.68;
758:     this.result = this.baseResult + this.spanResult * this.releaseScore * this.angleScore * (0.8 + 0.2 * speedFactor) + precision + rand(-0.35, 0.35);
759:     if (auto) this.result *= 0.9;
760:     this.result = clamp(this.result, this.maxResult * 0.48, this.maxResult);
761:     this.throwerX = this.x;
762:     this.startX = x + 1.2;
763:     this.landX = 36 + this.result;
764:     this.peak = this.H * (0.12 + this.result / 450);
765:     this.flightDur = 3.1 + this.result * 0.007;
766:     this.flightT = 0;
767:     this.state = 'flight';
768:     this.trail = [];
769:     this.game.sound.javelinThrow();
770:     this.game.shake = Math.max(this.game.shake, 6);
771:     this.game.flashScreen(0.22);
772:     this.game.toast(
773:       auto ? 'LATE RELEASE' : Math.abs(this.angle - this.optAngle) < 4 ? (this.isShot ? 'PERFECT ARC' : 'PERFECT ANGLE') : (this.isShot ? 'SHOT AWAY' : 'SPEAR AWAY'),
774:       Math.abs(this.angle - this.optAngle) < 4 ? 'gold' : '', 850
775:     );
776:     // Camera expands to follow the whole throw.
777:     this.camX = (this.startX + this.landX) / 2 - (this.W * 0.5) / this.meter;
778:   }
779: 
780:   update(dt) {
781:     this.phase += dt;
782:     if (this.state === 'ready') return;
783:     if (this.state === 'run') {
784:       this.runTime += dt;
785:       this.angleTime += dt;
786:       this.angle = this.optAngle + this.angleAmp * Math.sin(this.angleTime * 3.55 - 0.9);
787:       this.speed = 10.9 * smoothstep(0, 3.5, this.runTime);
788:       this.x += this.speed * dt;
789:       this.phase += this.speed * 0.92 * dt;
790:       if (this.x >= 36.35) {
791:         this.x = 36.2;
792:         this.throwSpear(true);
793:       }
794:       this.updateCamera(dt, this.x, 3.8);
795:       this.spawnDust();
796:     } else if (this.state === 'flight') {
797:       this.flightT += dt;
798:       const u = clamp(this.flightT / this.flightDur, 0, 1);
799:       this.x = lerp(this.startX, this.landX, u);
800:       const targetMeter = clamp(this.W / 102, 8.2, 18);
801:       this.meter = lerp(this.meter, targetMeter, 1 - Math.exp(-1.4 * dt));
802:       const targetCam = (this.startX + this.landX) / 2 - (this.W * 0.5) / this.meter;
803:       this.camX = lerp(this.camX, targetCam, 1 - Math.exp(-1.8 * dt));
804:       this.anchor = lerp(this.anchor, 0.5, 1 - Math.exp(-1.6 * dt));
805:       this.world.setCamera(this.camX, this.meter, this.anchor, 'javelin');
806:       if (u >= 1) this.land();
807:     } else if (this.state === 'landed') {
808:       this.landTimer += dt;
809:       const targetCam = (this.startX + this.landX) / 2 - (this.W * 0.5) / this.meter;
810:       this.camX = lerp(this.camX, targetCam, 1 - Math.exp(-1.2 * dt));
811:       this.world.setCamera(this.camX, this.meter, this.anchor, 'javelin');
812:       if (this.landTimer > 1.8) {
813:         this.state = 'done';
814:         this.done(this.result, { angle: this.angle, release: this.releaseScore });
815:         return;
816:       }
817:     }
818:     this.liveRank = 1 + this.game.fieldRank(this.id, this.state === 'landed' ? this.result : 0);
819:     this.jumbo.value = this.state === 'landed' ? this.result.toFixed(1) : this.state === 'flight' ? `${this.angle.toFixed(0)}°` : '0.00';
820:     this.hudState();
821:   }
822: 
823:   hudState() {
824:     const toLine = Math.max(0, 36 - this.x);
825:     const flying = this.state === 'flight';
826:     const clockValue = this.state === 'landed'
827:       ? fmtDist(this.result, 1)
828:       : flying ? fmtDist(this.result, 1) : toLine.toFixed(1);
829:     const clockUnit = this.state === 'landed' || flying ? 'm' : 'm';
830:     const clockLabel = this.state === 'landed' ? 'MEASURED' : flying ? 'PROJECTED' : this.isShot ? 'TO THE CIRCLE' : 'TO FOUL LINE';
831:     let prompt;
832:     const tap = this.game.touch ? 'TAP' : '↑';
833:     if (this.state === 'run') {
834:       prompt = {
835:         key: tap, title: this.isShot ? 'PUT AT THE LINE' : 'RELEASE AT THE LINE',
836:         sub: `Arm angle ${this.angle.toFixed(0)}° — find the gold band`,
837:         pulse: Math.abs(this.angle - this.optAngle) < 5
838:       };
839:     } else if (this.state === 'flight') {
840:       prompt = { key: '✓', title: this.isShot ? 'THE SHOT IS FLYING' : 'THE SPEAR IS FLYING', sub: 'The stadium is watching', pulse: false };
841:     } else if (this.state === 'landed') {
842:       prompt = { key: '✓', title: 'DISTANCE MEASURED', sub: `${this.result.toFixed(2)} metres`, pulse: false };
843:     } else {
844:       prompt = { visible: false };
845:     }
846:     this.hud({
847:       clock: clockValue,
848:       clockUnit,
849:       clockLabel,
850:       place: `${this.game.fieldRank(this.id, this.state === 'landed' ? this.result : 0)}`,
851:       meter: this.speed,
852:       meterMax: 11.5,
853:       meterUnit: 'M/S',
854:       meterLabel: 'APPROACH',
855:       prompt: { visible: true, ...prompt },
856:       action: true,
857:       actionLabel: this.state === 'flight' || this.state === 'landed' ? 'FLY' : this.isShot ? 'PUT' : 'THROW',
858:       actionSub: this.game.touch ? 'TAP HERE' : 'SPACE / TAP',
859:       actionHot: this.state === 'run' && this.x > 29,
860:       actionDisabled: this.state !== 'run',
861:       javelin: !this.isShot,
862:       angle: this.angle,
863:       angleValue: this.angle
864:     });
865:     this.game.setMiniBoard(
866:       this.game.fieldBoard(this.id, this.state === 'landed' ? this.result : null),
867:       'FIELD ORDER'
868:     );
869:   }
870: 
871:   spawnDust() {
872:     if (this.speed < 3) return;
873:     const crossed = Math.floor(this.phase / Math.PI);
874:     if (crossed !== this.lastPhase) {
875:       this.lastPhase = crossed;
876:       const x = this.world.sx(this.x) - 10;
877:       const y = this.game.groundY(1, 'javelin');
878:       this.game.spawnParticle({
879:         x, y: y - 2, vx: rand(-40, -8), vy: rand(-24, -4), life: rand(0.3, 0.55),
880:         size: rand(1.2, 3.2), color: 'rgba(255,216,160,.23)', gravity: 28
881:       });
882:     }
883:   }
884: 
885:   land() {
886:     this.state = 'landed';
887:     this.x = this.landX;
888:     this.landTimer = 0;
889:     this.game.sound.javelinLand();
890:     this.game.sound.cheer(1.1);
891:     this.game.shake = Math.max(this.game.shake, 5);
892:     const sx = this.world.sx(this.landX);
893:     const gy = this.game.groundY(1, 'javelin');
894:     this.game.burst(sx, gy - 5, 28, '#d6c393', 150, 0.75);
895:     this.game.burst(sx, gy - 5, 18, '#f8e2ad', 100, 0.5);
896:     this.game.toast(`${this.result.toFixed(2)} M`, 'gold', 1300);
897:     this.trail = [];
898:   }
899: 
900:   render(ctx) {
901:     this.paint();
902:     const ground = this.game.groundY(1, 'javelin');
903:     const baseScale = this.world.laneScale(1, 'javelin');
904:     const zoomScale = clamp(this.meter / clamp(this.W / 24, 16, 52), 0.16, 1);
905:     const scale = (this.state === 'flight' || this.state === 'landed') ? baseScale * zoomScale : baseScale;
906:     const athleteX = (this.state === 'flight' || this.state === 'landed') ? this.throwerX : this.x;
907:     const sx = this.world.sx(athleteX);
908: 
909:     if (this.state === 'run' || this.state === 'ready') {
910:       const pose = this.state === 'ready' ? 'idle' : 'run';
911:       drawAthlete(ctx, {
912:         x: sx, y: ground, scale, phase: this.phase, pose,
913:         speed: clamp(this.speed / 11, 0, 1), kit: this.game.playerKit,
914:         glow: 0.18, shadow: 1,
915:         javelin: this.isShot ? null : { angle: -0.52 }
916:       });
917:     } else if (this.state === 'flight') {
918:       const pose = this.flightT < 0.35 ? 'release' : 'idle';
919:       drawAthlete(ctx, {
920:         x: sx, y: ground, scale, phase: this.phase, pose,
921:         speed: 0.2, kit: this.game.playerKit, glow: 0.2, shadow: 1
922:       });
923:     } else {
924:       drawAthlete(ctx, {
925:         x: sx, y: ground, scale, phase: this.phase, pose: 'idle',
926:         speed: 0.1, kit: this.game.playerKit, glow: 0.15, shadow: 1
927:       });
928:     }
929: 
930:     if (this.state === 'flight') this.drawSpearFlight(ctx, ground, scale);
931:     if (this.state === 'landed') this.drawJavelinMeasurement(ctx, ground, scale);
932:   }
933: 
934:   drawShotFlight(ctx, ground) {
935:     const u = clamp(this.flightT / this.flightDur, 0, 1);
936:     const x = this.world.sx(this.x);
937:     const shoulder = 2 * this.meter;
938:     const y = ground - shoulder * (1 - u) - this.peak * Math.sin(Math.PI * u);
939:     const r = clamp(0.42 * this.meter, 5, 15);
940:     ctx.save();
941:     // trail
942:     for (let i = 1; i < 8; i++) {
943:       const uu = clamp(u - i * 0.018, 0, 1);
944:       const tx = this.world.sx(lerp(this.startX, this.landX, uu));
945:       const ty = ground - shoulder * (1 - uu) - this.peak * Math.sin(Math.PI * uu);
946:       ctx.fillStyle = `rgba(214,222,235,${0.16 * (1 - i / 8)})`;
947:       ctx.beginPath(); ctx.arc(tx, ty, r * 0.7, 0, Math.PI * 2); ctx.fill();
948:     }
949:     const g = ctx.createRadialGradient(x - r * 0.35, y - r * 0.35, r * 0.15, x, y, r);
950:     g.addColorStop(0, '#f4f7fb');
951:     g.addColorStop(0.45, '#aeb9c8');
952:     g.addColorStop(1, '#4f5b6c');
953:     ctx.fillStyle = g;
954:     ctx.beginPath(); ctx.arc(x, y, r, 0, Math.PI * 2); ctx.fill();
955:     ctx.strokeStyle = 'rgba(255,255,255,.45)';
956:     ctx.lineWidth = 1;
957:     ctx.stroke();
958:     ctx.restore();
959:   }
960: 
961:   drawSpearFlight(ctx, ground, scale) {
962:     if (this.isShot) return this.drawShotFlight(ctx, ground);
963:     const u = clamp(this.flightT / this.flightDur, 0, 1);
964:     const x = this.world.sx(this.x);
965:     const shoulder = 2.2 * this.meter;
966:     const y = ground - shoulder * (1 - u) - this.peak * Math.sin(Math.PI * u);
967:     const x2 = this.world.sx(lerp(this.startX, this.landX, clamp(u + 0.008, 0, 1)));
968:     const y2 = ground - shoulder * (1 - clamp(u + 0.008, 0, 1)) - this.peak * Math.sin(Math.PI * clamp(u + 0.008, 0, 1));
969:     const angle = Math.atan2(y2 - y, x2 - x);
970:     const len = clamp(2.7 * this.meter, 18, 110);
971:     const thick = clamp(0.08 * this.meter, 1.1, 3.2);
972:     ctx.save();
973:     ctx.translate(x, y);
974:     ctx.rotate(angle);
975:     const grad = ctx.createLinearGradient(-len / 2, 0, len / 2, 0);
976:     grad.addColorStop(0, '#6f5733');
977:     grad.addColorStop(0.45, '#e1c484');
978:     grad.addColorStop(0.8, '#f7ecc8');
979:     grad.addColorStop(1, '#ffffff');
980:     ctx.strokeStyle = grad;
981:     ctx.lineWidth = thick;
982:     ctx.lineCap = 'round';
983:     ctx.beginPath(); ctx.moveTo(-len / 2, 0); ctx.lineTo(len / 2, 0); ctx.stroke();
984:     ctx.fillStyle = '#f5f8fa';
985:     const tip = clamp(0.3 * this.meter, 3, 12);
986:     ctx.beginPath(); ctx.moveTo(len / 2 + tip, 0); ctx.lineTo(len / 2 - tip * 0.7, -tip * 0.55); ctx.lineTo(len / 2 - tip * 0.7, tip * 0.55); ctx.closePath(); ctx.fill();
987:     ctx.restore();
988: 
989:     // speed trail
990:     for (let i = 0; i < 7; i++) {
991:       const uu = clamp(u - i * 0.012, 0, 1);
992:       const tx = this.world.sx(lerp(this.startX, this.landX, uu));
993:       const ty = ground - shoulder * (1 - uu) - this.peak * Math.sin(Math.PI * uu);
994:       ctx.fillStyle = `rgba(255,231,164,${0.13 * (1 - i / 7)})`;
995:       ctx.beginPath(); ctx.arc(tx, ty, 1.6, 0, Math.PI * 2); ctx.fill();
996:     }
997:   }
998: 
999:   drawJavelinMeasurement(ctx, ground, scale) {
1000:     const lineX = this.world.sx(36);
1001:     const landX = this.world.sx(this.landX);
1002:     const y = ground + 16;
1003:     ctx.save();
1004:     ctx.strokeStyle = 'rgba(247,201,80,.82)';
